__hydrateVak("havo","ec",{"B":{"sv":[{"v":"Wat zijn opportuniteitskosten?","o":["de waarde van het beste alternatief dat je niet kiest","het geld dat je uitgeeft","de totale productiekosten","de belasting die je betaalt"],"c":0,"d":2,"u":"Het beste alternatief dat je opgeeft.","uo":["Klopt: het beste alternatief dat je opgeeft.","Nee, het gaat om het gemiste alternatief.","Nee, dat zijn gewone kosten.","Nee, dat is belasting."],"uh":"Opportuniteitskosten: het beste opgegeven alternatief."},{"v":"Welke vier productiefactoren worden onderscheiden?","o":["geld, goud, grond en goederen","arbeid, natuur, kapitaal en ondernemerschap","vraag, aanbod, prijs en winst","loon, huur, rente en winst"],"c":1,"d":2,"u":"Dat zijn de vier productiefactoren.","uo":["Nee, dat klopt niet.","Klopt: dat zijn de vier productiefactoren.","Nee, dat zijn marktbegrippen.","Nee, dat zijn de beloningen."],"uh":"Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap."},{"v":"Wat is het BBP per hoofd?","o":["het inkomen van de rijkste inwoner","de totale productie van een land","het BBP gedeeld door het aantal inwoners","de staatsschuld per inwoner"],"c":2,"d":2,"u":"Het BBP per inwoner.","uo":["Nee, dat is een gemiddelde over iedereen.","Nee, dat is het totale BBP.","Klopt: het BBP per inwoner.","Nee, dat is schuld, geen productie."],"uh":"BBP per hoofd: BBP / aantal inwoners."},{"v":"Wat is het verschil tussen een lek en een injectie in de kringloop?","o":["een injectie verlaat de kringloop","ze zijn hetzelfde","een lek komt in de kringloop","een lek verlaat de kringloop, een injectie komt erin"],"c":3,"d":3,"u":"Lek eruit, injectie erin.","uo":["Nee, dat is precies omgedraaid.","Nee, ze verschillen.","Nee, dat is precies omgedraaid.","Klopt: lek eruit, injectie erin."],"uh":"Lek: geld eruit; injectie: geld erin."},{"v":"Waarom dwingt schaarste tot keuzes?","o":["de behoeften zijn groter dan de beschikbare middelen","er is te veel van alles","geld raakt op door inflatie","de overheid verbiedt het"],"c":0,"d":2,"u":"Je kunt niet alles hebben, dus je kiest.","uo":["Klopt: je kunt niet alles hebben, dus je kiest.","Nee, dan is er geen schaarste.","Nee, dat is inflatie.","Nee, dat is geen schaarste."],"uh":"Schaarste: behoeften > middelen, dus kiezen."},{"v":"Wat zijn marginale kosten?","o":["de totale productiekosten","de extra kosten van één eenheid meer produceren","de vaste kosten","de gemiddelde kosten"],"c":1,"d":2,"u":"De kosten van één extra eenheid.","uo":["Nee, dat is het totaal.","Klopt: de kosten van één extra eenheid.","Nee, dat zijn vaste kosten.","Nee, dat is het gemiddelde."],"uh":"Marginale kosten: één eenheid extra."},{"v":"Wat is het verschil tussen materiële en immateriële welvaart?","o":["materieel is gezondheid","ze zijn hetzelfde","materieel is inkomen en bezit, immaterieel is bijvoorbeeld gezondheid","immaterieel is inkomen"],"c":2,"d":3,"u":"Geld en bezit tegenover niet-geldzaken.","uo":["Nee, dat is omgedraaid.","Nee, ze verschillen.","Klopt: geld en bezit tegenover niet-geldzaken.","Nee, dat is omgedraaid."],"uh":"Materieel: inkomen/bezit; immaterieel: gezondheid, milieu, vrije tijd."},{"v":"Welke beloning hoort bij de productiefactor ondernemerschap?","o":["huur","loon","rente","winst"],"c":3,"d":2,"u":"Ondernemerschap levert winst op.","uo":["Nee, huur hoort bij natuur.","Nee, loon hoort bij arbeid.","Nee, rente hoort bij kapitaal.","Klopt: ondernemerschap levert winst op."],"uh":"Ondernemerschap → winst."},{"v":"Wat meet het BBP?","o":["de totale marktwaarde van alle productie in een land per jaar","het spaargeld van de bevolking","de staatsschuld","de totale import"],"c":0,"d":2,"u":"Het BBP is de totale productiewaarde.","uo":["Klopt: het BBP is de totale productiewaarde.","Nee, dat is geen BBP.","Nee, dat is de schuld.","Nee, dat is import."],"uh":"BBP: totale productie van een land per jaar."},{"v":"Wat is het verschil tussen loon en rente als beloningen?","o":["ze zijn hetzelfde","loon is de beloning voor arbeid, rente voor kapitaal","loon is voor kapitaal","rente is voor arbeid"],"c":1,"d":2,"u":"Arbeid → loon, kapitaal → rente.","uo":["Nee, ze verschillen.","Klopt: arbeid → loon, kapitaal → rente.","Nee, dat is omgedraaid.","Nee, dat is omgedraaid."],"uh":"Loon: arbeid; rente: kapitaal."},{"v":"Wat is het verschil tussen BBP en BNP?","o":["BBP telt het buitenland mee","ze zijn hetzelfde","BBP is binnen de grenzen, BNP telt ook inwoners in het buitenland","BNP is alleen binnenlands"],"c":2,"d":3,"u":"BBP is geografisch, BNP volgt de inwoners.","uo":["Nee, dat doet het BNP.","Nee, ze verschillen.","Klopt: BBP is geografisch, BNP volgt de inwoners.","Nee, dat is het BBP."],"uh":"BBP: binnen de grenzen; BNP: ook inwoners in het buitenland."},{"v":"Wat is het rationele moment om te stoppen met produceren?","o":["nooit","als de voorraad op is","als het personeel moe is","als de marginale kosten gelijk zijn aan de opbrengsten"],"c":3,"d":3,"u":"Produceren loont tot MK = opbrengst.","uo":["Nee, er is wel een optimum.","Nee, dat is een praktisch punt, geen economisch.","Nee, dat is geen economische regel.","Klopt: produceren loont tot MK = opbrengst."],"uh":"Stoppen bij marginale kosten = opbrengst."},{"v":"Wat is het free-rider-probleem bij collectieve goederen?","o":["mensen profiteren zonder eraan mee te betalen","niemand kan het goed gebruiken","het goed is te duur","de overheid verbiedt het"],"c":0,"d":3,"u":"Freeriders profiteren zonder bij te dragen.","uo":["Klopt: freeriders profiteren zonder bij te dragen.","Nee, iedereen kan het juist gebruiken.","Nee, prijs is niet het probleem.","Nee, dat is geen meeliften."],"uh":"Free-rider: profiteren zonder meebetalen."},{"v":"Wat is het verschil tussen een economisch goed en een vrij goed?","o":["ze zijn hetzelfde","een economisch goed is schaars met een prijs, een vrij goed heeft geen prijs","een economisch goed is gratis","een vrij goed is schaars"],"c":1,"d":2,"u":"Schaars-met-prijs tegenover niet-schaars.","uo":["Nee, ze verschillen.","Klopt: schaars-met-prijs tegenover niet-schaars.","Nee, dat is een vrij goed.","Nee, een vrij goed is niet schaars."],"uh":"Economisch goed: schaars met prijs; vrij goed: geen prijs."},{"v":"Kies je voor studeren, dan mis je het loon van werken. Welk begrip past hierbij?","o":["BBP per hoofd","Vrij goed","Opportuniteitskosten","BBP"],"c":2,"d":1,"u":"Kies je voor studeren, dan mis je het loon van werken. Dat past bij Opportuniteitskosten: best opgegeven alternatief.","uo":["Nee, dat hoort bij BBP per hoofd: bbp per inwoner.","Nee, dat hoort bij Vrij goed: niet schaars, geen prijs.","Klopt: best opgegeven alternatief.","Nee, dat hoort bij BBP: totale productie per jaar."],"uh":"Opportuniteitskosten: best opgegeven alternatief."},{"v":"Investeringen en overheidsuitgaven pompen geld in de kringloop. Om welk begrip gaat het?","o":["Collectief goed","Schaarste","BBP","Injectie"],"c":3,"d":1,"u":"Investeringen en overheidsuitgaven pompen geld in de kringloop. Dat past bij Injectie: geld komt in de kringloop.","uo":["Nee, dat hoort bij Collectief goed: niet-uitsluitbaar en niet-rivaliserend.","Nee, dat hoort bij Schaarste: behoeften groter dan middelen.","Nee, dat hoort bij BBP: totale productie per jaar.","Klopt: geld komt in de kringloop."],"uh":"Injectie: geld komt in de kringloop."},{"v":"Geld dat in de kringloop komt. Welk begrip herken je hier?","o":["Injectie","Schaarste","BBP","Collectief goed"],"c":0,"d":1,"u":"Geld dat in de kringloop komt. Dat past bij Injectie: geld komt in de kringloop.","uo":["Klopt: geld komt in de kringloop.","Nee, dat hoort bij Schaarste: behoeften groter dan middelen.","Nee, dat hoort bij BBP: totale productie per jaar.","Nee, dat hoort bij Collectief goed: niet-uitsluitbaar en niet-rivaliserend."],"uh":"Injectie: geld komt in de kringloop."},{"v":"Een goed dat niet-uitsluitbaar en niet-rivaliserend is. Wat is hier aan de hand?","o":["Injectie","Collectief goed","BBP per hoofd","Productiefactoren"],"c":1,"d":1,"u":"Een goed dat niet-uitsluitbaar en niet-rivaliserend is. Dat past bij Collectief goed: niet-uitsluitbaar en niet-rivaliserend.","uo":["Nee, dat hoort bij Injectie: geld komt in de kringloop.","Klopt: niet-uitsluitbaar en niet-rivaliserend.","Nee, dat hoort bij BBP per hoofd: bbp per inwoner.","Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap."],"uh":"Collectief goed: niet-uitsluitbaar en niet-rivaliserend."},{"v":"Iedereen profiteert van straatverlichting, niemand kun je uitsluiten. Welk begrip past hierbij?","o":["BBP per hoofd","Injectie","Collectief goed","Productiefactoren"],"c":2,"d":1,"u":"Iedereen profiteert van straatverlichting, niemand kun je uitsluiten. Dat past bij Collectief goed: niet-uitsluitbaar en niet-rivaliserend.","uo":["Nee, dat hoort bij BBP per hoofd: bbp per inwoner.","Nee, dat hoort bij Injectie: geld komt in de kringloop.","Klopt: niet-uitsluitbaar en niet-rivaliserend.","Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap."],"uh":"Collectief goed: niet-uitsluitbaar en niet-rivaliserend."},{"v":"Geld dat de economische kringloop verlaat. Om welk begrip gaat het?","o":["Opportuniteitskosten","BBP per hoofd","Collectief goed","Lek"],"c":3,"d":1,"u":"Geld dat de economische kringloop verlaat. Dat past bij Lek: geld verlaat de kringloop.","uo":["Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Nee, dat hoort bij BBP per hoofd: bbp per inwoner.","Nee, dat hoort bij Collectief goed: niet-uitsluitbaar en niet-rivaliserend.","Klopt: geld verlaat de kringloop."],"uh":"Lek: geld verlaat de kringloop."},{"v":"De kosten van één eenheid extra. Welk begrip herken je hier?","o":["Marginale kosten","Opportuniteitskosten","Vrij goed","Schaarste"],"c":0,"d":3,"u":"De kosten van één eenheid extra. Dat past bij Marginale kosten: kosten van één eenheid extra.","uo":["Klopt: kosten van één eenheid extra.","Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Nee, dat hoort bij Vrij goed: niet schaars, geen prijs.","Nee, dat hoort bij Schaarste: behoeften groter dan middelen."],"uh":"Marginale kosten: kosten van één eenheid extra."},{"v":"De extra kosten om één product meer te maken. Wat is hier aan de hand?","o":["BBP","Marginale kosten","Productiefactoren","Schaarste"],"c":1,"d":1,"u":"De extra kosten om één product meer te maken. Dat past bij Marginale kosten: kosten van één eenheid extra.","uo":["Nee, dat hoort bij BBP: totale productie per jaar.","Klopt: kosten van één eenheid extra.","Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap.","Nee, dat hoort bij Schaarste: behoeften groter dan middelen."],"uh":"Marginale kosten: kosten van één eenheid extra."},{"v":"De totale productie van een land per jaar. Welk begrip past hierbij?","o":["Marginale kosten","BBP per hoofd","BBP","Productiefactoren"],"c":2,"d":3,"u":"De totale productie van een land per jaar. Dat past bij BBP: totale productie per jaar.","uo":["Nee, dat hoort bij Marginale kosten: kosten van één eenheid extra.","Nee, dat hoort bij BBP per hoofd: bbp per inwoner.","Klopt: totale productie per jaar.","Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap."],"uh":"BBP: totale productie per jaar."},{"v":"De totale marktwaarde van alles wat een land in een jaar produceert. Om welk begrip gaat het?","o":["Opportuniteitskosten","Lek","Collectief goed","BBP"],"c":3,"d":1,"u":"De totale marktwaarde van alles wat een land in een jaar produceert. Dat past bij BBP: totale productie per jaar.","uo":["Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Nee, dat hoort bij Lek: geld verlaat de kringloop.","Nee, dat hoort bij Collectief goed: niet-uitsluitbaar en niet-rivaliserend.","Klopt: totale productie per jaar."],"uh":"BBP: totale productie per jaar."},{"v":"De vier bronnen waarmee je produceert. Welk begrip herken je hier?","o":["Productiefactoren","BBP","Opportuniteitskosten","Lek"],"c":0,"d":3,"u":"De vier bronnen waarmee je produceert. Dat past bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap.","uo":["Klopt: arbeid, natuur, kapitaal, ondernemerschap.","Nee, dat hoort bij BBP: totale productie per jaar.","Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Nee, dat hoort bij Lek: geld verlaat de kringloop."],"uh":"Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap."},{"v":"Een goed dat niet schaars is en geen prijs heeft. Wat is hier aan de hand?","o":["Productiefactoren","Vrij goed","Schaarste","Injectie"],"c":1,"d":1,"u":"Een goed dat niet schaars is en geen prijs heeft. Dat past bij Vrij goed: niet schaars, geen prijs.","uo":["Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap.","Klopt: niet schaars, geen prijs.","Nee, dat hoort bij Schaarste: behoeften groter dan middelen.","Nee, dat hoort bij Injectie: geld komt in de kringloop."],"uh":"Vrij goed: niet schaars, geen prijs."},{"v":"Behoeften groter dan de beschikbare middelen. Welk begrip past hierbij?","o":["Productiefactoren","Opportuniteitskosten","Schaarste","Vrij goed"],"c":2,"d":3,"u":"Behoeften groter dan de beschikbare middelen. Dat past bij Schaarste: behoeften groter dan middelen.","uo":["Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap.","Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Klopt: behoeften groter dan middelen.","Nee, dat hoort bij Vrij goed: niet schaars, geen prijs."],"uh":"Schaarste: behoeften groter dan middelen."},{"v":"Sparen en belasting halen geld uit de kringloop. Om welk begrip gaat het?","o":["Opportuniteitskosten","BBP per hoofd","Collectief goed","Lek"],"c":3,"d":1,"u":"Sparen en belasting halen geld uit de kringloop. Dat past bij Lek: geld verlaat de kringloop.","uo":["Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Nee, dat hoort bij BBP per hoofd: bbp per inwoner.","Nee, dat hoort bij Collectief goed: niet-uitsluitbaar en niet-rivaliserend.","Klopt: geld verlaat de kringloop."],"uh":"Lek: geld verlaat de kringloop."},{"v":"De waarde van het beste alternatief dat je opgeeft. Welk begrip herken je hier?","o":["Opportuniteitskosten","Marginale kosten","BBP","BBP per hoofd"],"c":0,"d":2,"u":"De waarde van het beste alternatief dat je opgeeft. Dat past bij Opportuniteitskosten: best opgegeven alternatief.","uo":["Klopt: best opgegeven alternatief.","Nee, dat hoort bij Marginale kosten: kosten van één eenheid extra.","Nee, dat hoort bij BBP: totale productie per jaar.","Nee, dat hoort bij BBP per hoofd: bbp per inwoner."],"uh":"Opportuniteitskosten: best opgegeven alternatief."},{"v":"Het BBP per inwoner. Wat is hier aan de hand?","o":["BBP","BBP per hoofd","Vrij goed","Lek"],"c":1,"d":3,"u":"Het BBP per inwoner. Dat past bij BBP per hoofd: bbp per inwoner.","uo":["Nee, dat hoort bij BBP: totale productie per jaar.","Klopt: bbp per inwoner.","Nee, dat hoort bij Vrij goed: niet schaars, geen prijs.","Nee, dat hoort bij Lek: geld verlaat de kringloop."],"uh":"BBP per hoofd: bbp per inwoner."},{"v":"Er is minder van iets dan mensen willen hebben, dus je moet kiezen. Welk begrip past hierbij?","o":["Productiefactoren","BBP per hoofd","Schaarste","Vrij goed"],"c":2,"d":1,"u":"Er is minder van iets dan mensen willen hebben, dus je moet kiezen. Dat past bij Schaarste: behoeften groter dan middelen.","uo":["Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap.","Nee, dat hoort bij BBP per hoofd: bbp per inwoner.","Klopt: behoeften groter dan middelen.","Nee, dat hoort bij Vrij goed: niet schaars, geen prijs."],"uh":"Schaarste: behoeften groter dan middelen."},{"v":"Het BBP gedeeld door het aantal inwoners, om welvaart te vergelijken. Om welk begrip gaat het?","o":["Opportuniteitskosten","BBP","Injectie","BBP per hoofd"],"c":3,"d":2,"u":"Het BBP gedeeld door het aantal inwoners, om welvaart te vergelijken. Dat past bij BBP per hoofd: bbp per inwoner.","uo":["Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Nee, dat hoort bij BBP: totale productie per jaar.","Nee, dat hoort bij Injectie: geld komt in de kringloop.","Klopt: bbp per inwoner."],"uh":"BBP per hoofd: bbp per inwoner."},{"v":"Arbeid, natuur, kapitaal en ondernemerschap samen maken productie mogelijk. Welk begrip herken je hier?","o":["Productiefactoren","BBP","Opportuniteitskosten","Lek"],"c":0,"d":3,"u":"Arbeid, natuur, kapitaal en ondernemerschap samen maken productie mogelijk. Dat past bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap.","uo":["Klopt: arbeid, natuur, kapitaal, ondernemerschap.","Nee, dat hoort bij BBP: totale productie per jaar.","Nee, dat hoort bij Opportuniteitskosten: best opgegeven alternatief.","Nee, dat hoort bij Lek: geld verlaat de kringloop."],"uh":"Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap."},{"v":"Lucht is er in overvloed en kost niets. Wat is hier aan de hand?","o":["Productiefactoren","Vrij goed","Schaarste","Injectie"],"c":1,"d":1,"u":"Lucht is er in overvloed en kost niets. Dat past bij Vrij goed: niet schaars, geen prijs.","uo":["Nee, dat hoort bij Productiefactoren: arbeid, natuur, kapitaal, ondernemerschap.","Klopt: niet schaars, geen prijs.","Nee, dat hoort bij Schaarste: behoeften groter dan middelen.","Nee, dat hoort bij Injectie: geld komt in de kringloop."],"uh":"Vrij goed: niet schaars, geen prijs."}],"oe":[{"bron":"Artikel","ctx":"De prijzen van dagelijkse boodschappen zijn de afgelopen jaren sterk gestegen, wat consumenten dwingt bewuster keuzes te maken. Supermarkten reageren hierop door meer aanbiedingen te gebruiken en huismerken prominenter in de schappen te plaatsen. Veel consumenten stappen over op goedkopere alternatieven, waardoor de vraag naar A-merken daalt. Producenten van deze merken proberen hun positie te behouden door te investeren in marketing, kwaliteitsverbetering en loyaliteitsprogramma's. Tegelijkertijd spelen grondstofprijzen een grote rol: wanneer de kosten van energie, transport of landbouwproducten stijgen, worden deze kosten vaak doorberekend aan de consument. Hierdoor ontstaat een ketenreactie waarbij producenten, supermarkten en consumenten voortdurend op elkaar reageren. De markt voor dagelijkse boodschappen laat zien hoe prijselasticiteit, concurrentie en consumentengedrag elkaar beïnvloeden.","v":"Leg uit hoe stijgende kosten bij producenten kunnen leiden tot veranderingen in het koopgedrag van consumenten.","o":[""],"c":0,"u":"Wanneer producenten hogere kosten hebben, stijgen de verkoopprijzen. Consumenten reageren hierop door goedkopere alternatieven te zoeken. Hierdoor neemt de vraag naar A-merken af en stijgt de vraag naar huismerken. Dit laat zien dat consumenten prijsgevoelig zijn. De keten van kostenstijgingen beïnvloedt dus direct het koopgedrag."},{"bron":"Grafiek","ctx":"Grafiek-beschrijving: 'Lijngrafiek met de vraag naar A-merken en huismerken tussen 2015 en 2025. A-merken dalen licht, huismerken stijgen sterk.'","v":"Leg uit hoe de trend in de grafiek past bij prijselasticiteit van de vraag.","o":[""],"c":0,"u":"De daling van A-merken laat zien dat consumenten reageren op hogere prijzen. De stijging van huismerken toont dat zij overstappen naar goedkopere alternatieven. Dit past bij een elastische vraag: consumenten veranderen hun gedrag wanneer prijzen stijgen. De grafiek ondersteunt dit duidelijk."},{"bron":"Artikel","ctx":"Veel bedrijven gebruiken prijsdiscriminatie om hun omzet te vergroten. Dit betekent dat dezelfde dienst of hetzelfde product tegen verschillende prijzen wordt aangeboden aan verschillende groepen consumenten. Denk aan bioscopen die lagere prijzen rekenen voor studenten of ouderen, of luchtvaartmaatschappijen die hogere prijzen vragen tijdens vakantieperiodes. Het doel is om consumenten met een hogere betalingsbereidheid meer te laten betalen, terwijl prijsgevoelige groepen toch worden bediend. Digitale platforms maken prijsdiscriminatie nog eenvoudiger, omdat bedrijven steeds meer gegevens verzamelen over koopgedrag en voorkeuren. Hierdoor kunnen prijzen dynamisch worden aangepast op basis van vraag, tijdstip of klantprofiel.","v":"Leg uit waarom bedrijven prijsdiscriminatie toepassen.","o":[""],"c":0,"u":"Bedrijven passen prijsdiscriminatie toe om hun omzet te verhogen. Ze laten consumenten met een hogere betalingsbereidheid meer betalen. Tegelijk bedienen ze prijsgevoelige groepen met lagere prijzen. Hierdoor vergroten ze hun totale afzet. Digitale data maakt dit proces nog efficiënter."},{"bron":"Foto","ctx":"Foto-beschrijving: 'Schap in een supermarkt met A-merken bovenaan en huismerken op ooghoogte prominent gepresenteerd.'","v":"Leg uit hoe schapindeling invloed heeft op consumentengedrag.","o":[""],"c":0,"u":"Producten op ooghoogte worden sneller gekozen. Supermarkten plaatsen daarom huismerken op strategische plekken. Hierdoor stijgt de verkoop van deze producten. De indeling beïnvloedt dus direct het koopgedrag van consumenten."},{"bron":"Artikel","ctx":"Door de groei van online winkelen is de concurrentie tussen webshops enorm toegenomen. Consumenten vergelijken prijzen eenvoudig via vergelijkingssites, waardoor bedrijven gedwongen worden scherp te prijzen. Tegelijkertijd spelen bezorgkosten en levertijd een steeds grotere rol in de keuze van consumenten. Bedrijven investeren daarom in efficiënte logistiek en snelle levering. De markt wordt gekenmerkt door lage marges en hoge volumes, waardoor schaalvoordelen belangrijk zijn. Grote spelers kunnen hierdoor goedkoper werken dan kleine webshops, wat leidt tot verdere concentratie in de markt.","v":"Leg uit waarom schaalvoordelen belangrijk zijn voor webshops.","o":[""],"c":0,"u":"Schaalvoordelen zorgen voor lagere kosten per product. Grote webshops kunnen goedkoper inkopen en efficiënter bezorgen. Hierdoor kunnen zij lagere prijzen aanbieden. Dit maakt het moeilijk voor kleine webshops om te concurreren. Schaalvoordelen bepalen dus de marktpositie."},{"bron":"HAVO Economie CE 2024 Tijdvak 1 (vraag 4)","ctx":"In een cao-discussie wijst de vakbond erop dat de gestegen arbeidsproductiviteit de productiekosten verlaagt.","v":"Leg uit dat een stijging van de arbeidsproductiviteit leidt tot lagere productiekosten.","o":[""],"c":0,"u":"Een hogere arbeidsproductiviteit betekent dat er minder arbeid nodig is om hetzelfde te produceren. Daardoor dalen de loonkosten per product, en dus de totale productiekosten."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 12 (HA-1210-a-25-1-o)","ctx":"Bedrijf X: omzet EUR 500.000, variabele kosten EUR 300.000, vaste kosten EUR 150.000.","v":"(a) Bereken de dekkingsbijdrage.\n(b) Bereken de winst.\n(c) Wat is het break-even omzet als variabele kosten 60% van omzet zijn?","o":[""],"c":0,"u":"(a) DB = 500.000 - 300.000 = EUR 200.000.\n(b) Winst = 200.000 - 150.000 = EUR 50.000.\n(c) Break-even: VK=0,6*omzet. DB=0,4*omzet=FK. Omzet=150.000/0,4=EUR 375.000."}],"begrippen":[{"t":"Schaarste","d":"dat de behoeften groter zijn dan de beschikbare middelen"},{"t":"Opportuniteitskosten","d":"de waarde van het beste alternatief dat je niet kiest"},{"t":"Productiefactoren","d":"arbeid, natuur, kapitaal en ondernemerschap"},{"t":"BBP","d":"de totale marktwaarde van alle productie in een land per jaar"},{"t":"BBP per hoofd","d":"het BBP gedeeld door het aantal inwoners"},{"t":"Marginale kosten","d":"de extra kosten van één eenheid meer produceren"},{"t":"Lek","d":"geld dat de economische kringloop verlaat, zoals sparen of belasting"},{"t":"Injectie","d":"geld dat in de kringloop komt en de economie stimuleert"},{"t":"Collectief goed","d":"een goed dat niet-uitsluitbaar en niet-rivaliserend is"},{"t":"Vrij goed","d":"een goed dat niet schaars is en geen prijs heeft"}],"sam":"<div class=\"sam-intro\"><strong>Schaarste</strong> dwingt tot keuzes: behoeften zijn groter dan de middelen. Elke keuze heeft <strong>opportuniteitskosten</strong>. De vier <strong>productiefactoren</strong> (arbeid, natuur, kapitaal, ondernemerschap) leveren loon, huur, rente en winst op. De welvaart meet je met het <strong>BBP</strong>, het beste per hoofd.</div><div class=\"sam-head\">1. Schaarste en keuze</div><p><strong>Schaarste</strong> betekent dat de behoeften groter zijn dan de beschikbare middelen, dus je moet kiezen. De <strong>opportuniteitskosten</strong> zijn de waarde van het beste alternatief dat je opgeeft. <strong>Marginale kosten</strong> zijn de extra kosten van één eenheid meer; produceren loont zolang die onder de opbrengst blijven.</p><div class=\"sam-head\">2. Productiefactoren en BBP</div><p>De vier <strong>productiefactoren</strong> met hun beloning: arbeid (loon), natuur (huur/pacht), kapitaal (rente), ondernemerschap (winst). Het <strong>BBP</strong> is de totale marktwaarde van alle productie in een land per jaar; het <strong>BBP per hoofd</strong> corrigeert voor de bevolkingsomvang. Bij een <strong>collectief goed</strong> ontstaat het <strong>free-rider-probleem</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Schaarste</div><div class=\"sam-definitie-body\">dat de behoeften groter zijn dan de beschikbare middelen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Opportuniteitskosten</div><div class=\"sam-definitie-body\">de waarde van het beste alternatief dat je niet kiest.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Productiefactoren</div><div class=\"sam-definitie-body\">arbeid, natuur, kapitaal en ondernemerschap.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">BBP</div><div class=\"sam-definitie-body\">de totale marktwaarde van alle productie in een land per jaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">BBP per hoofd</div><div class=\"sam-definitie-body\">het BBP gedeeld door het aantal inwoners.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Marginale kosten</div><div class=\"sam-definitie-body\">de extra kosten van één eenheid meer produceren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lek</div><div class=\"sam-definitie-body\">geld dat de economische kringloop verlaat, zoals sparen of belasting.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Injectie</div><div class=\"sam-definitie-body\">geld dat in de kringloop komt en de economie stimuleert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Collectief goed</div><div class=\"sam-definitie-body\">een goed dat niet-uitsluitbaar en niet-rivaliserend is.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vrij goed</div><div class=\"sam-definitie-body\">een goed dat niet schaars is en geen prijs heeft.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Schaarste»</b> is behoeften groter dan middelen, terwijl <b>«Opportuniteitskosten»</b> best opgegeven alternatief is. <b>«Opportuniteitskosten»</b> is best opgegeven alternatief, terwijl <b>«Marginale kosten»</b> kosten van één eenheid extra is. <b>«Productiefactoren»</b> is arbeid, natuur, kapitaal, ondernemerschap, terwijl <b>«BBP»</b> totale productie per jaar is. <b>«BBP»</b> is totale productie per jaar, terwijl <b>«BBP per hoofd»</b> bbp per inwoner is.</div>"},"C":{"sv":[{"v":"Welke prijs is bereikt wanneer de gevraagde hoeveelheid gelijk is aan de aangeboden hoeveelheid?","o":["de evenwichtsprijs","de maximumprijs","de minimumprijs","de kostprijs"],"c":0,"d":2,"u":"Bij evenwicht is vraag = aanbod.","uo":["Klopt: bij evenwicht is vraag = aanbod.","Nee, dat is een prijsplafond.","Nee, dat is een prijsbodem.","Nee, dat is een bedrijfsbegrip."],"uh":"Evenwichtsprijs: vraag = aanbod."},{"v":"Welk begrip beschrijft dat de vraag sterk reageert op een prijsverandering (|Ev| > 1)?","o":["inelastische vraag","elastische vraag","evenwichtsvraag","collectieve vraag"],"c":1,"d":3,"u":"Sterke reactie is elastische vraag.","uo":["Nee, dat reageert juist zwak.","Klopt: sterke reactie is elastische vraag.","Nee, dat is geen vakterm.","Nee, dat bestaat zo niet."],"uh":"Elastische vraag: sterke reactie op de prijs."},{"v":"Welk begrip beschrijft kosten of baten die derden treffen buiten de prijs om?","o":["een meritgoed","consumentensurplus","een extern effect","de evenwichtsprijs"],"c":2,"d":3,"u":"Derden buiten de transactie: extern effect.","uo":["Nee, dat is een goed dat wordt gestimuleerd.","Nee, dat is voordeel voor de koper.","Klopt: derden buiten de transactie: extern effect.","Nee, dat is een prijs."],"uh":"Extern effect: raakt derden buiten de prijs."},{"v":"Welk markttype heeft weinig grote aanbieders die elkaars strategie in de gaten houden?","o":["monopolistische concurrentie","volkomen concurrentie","monopolie","oligopolie"],"c":3,"d":3,"u":"Een oligopolie is een kleine groep grote aanbieders.","uo":["Nee, dat heeft veel aanbieders met verschillende producten.","Nee, dat heeft juist veel aanbieders.","Nee, dat is één aanbieder.","Klopt: een oligopolie is een kleine groep grote aanbieders."],"uh":"Oligopolie: weinig grote, onderling afhankelijke aanbieders."},{"v":"Welk instrument legt een prijsplafond onder het evenwicht en veroorzaakt een tekort?","o":["een maximumprijs","een minimumprijs","een subsidie","een accijns"],"c":0,"d":3,"u":"Een maximumprijs onder het evenwicht geeft een tekort.","uo":["Klopt: een maximumprijs onder het evenwicht geeft een tekort.","Nee, dat geeft een overschot.","Nee, dat verlaagt de prijs anders.","Nee, dat is een belasting."],"uh":"Maximumprijs onder evenwicht: tekort."},{"v":"Wat gebeurt er met de vraagcurve als het inkomen van consumenten stijgt?","o":["de curve schuift naar links","de curve schuift naar rechts: bij elke prijs meer vraag","de curve blijft gelijk","de curve wordt verticaal"],"c":1,"d":2,"u":"Meer inkomen betekent meer vraag.","uo":["Nee, dat zou bij minder inkomen zijn.","Klopt: meer inkomen betekent meer vraag.","Nee, de vraag verandert.","Nee, de vorm verandert niet zo."],"uh":"Meer inkomen: vraagcurve naar rechts."},{"v":"Wat is consumentensurplus?","o":["de totale omzet","de winst van de producent","het verschil tussen betalingsbereidheid en betaalde prijs","de belasting op een product"],"c":2,"d":3,"u":"Het voordeel doordat je minder betaalt dan je wilde.","uo":["Nee, dat is omzet.","Nee, dat is producentensurplus.","Klopt: het voordeel doordat je minder betaalt dan je wilde.","Nee, dat is belasting."],"uh":"Consumentensurplus: betalingsbereidheid − prijs."},{"v":"Wat zegt een positieve kruiselasticiteit over twee goederen?","o":["ze zijn collectieve goederen","ze zijn complementair","ze hebben niets met elkaar te maken","ze zijn substituten (vervangers)"],"c":3,"d":3,"u":"Positief betekent dat ze elkaar vervangen.","uo":["Nee, dat gaat niet over collectieve goederen.","Nee, complementair geeft een negatieve waarde.","Nee, dan zou de waarde nul zijn.","Klopt: positief betekent dat ze elkaar vervangen."],"uh":"Kruiselasticiteit positief: substituten."},{"v":"Wat is een collectief goed?","o":["een goed dat niet-uitsluitbaar en niet-rivaliserend is","een goed dat maar één persoon kan gebruiken","een luxeproduct","een goed zonder prijs op de markt"],"c":0,"d":3,"u":"Niemand kun je uitsluiten en het raakt niet op.","uo":["Klopt: niemand kun je uitsluiten en het raakt niet op.","Nee, dat is een privégoed.","Nee, luxe zegt niets over collectiviteit.","Nee, dat is een vrij goed."],"uh":"Collectief goed: niet-uitsluitbaar en niet-rivaliserend."},{"v":"Wat is het verschil tussen volkomen concurrentie en een monopolie?","o":["ze zijn hetzelfde","veel kleine aanbieders zonder prijsmacht versus één prijszetter","volkomen concurrentie heeft één aanbieder","een monopolie heeft veel aanbieders"],"c":1,"d":2,"u":"Veel aanbieders tegenover één.","uo":["Nee, ze verschillen sterk.","Klopt: veel aanbieders tegenover één.","Nee, dat is een monopolie.","Nee, dat is volkomen concurrentie."],"uh":"Volkomen concurrentie: veel kleine; monopolie: één prijszetter."},{"v":"Hoe beïnvloedt een subsidie op een product de markt?","o":["de prijs stijgt en het aanbod daalt","de vraagcurve schuift naar links","de aanbodcurve schuift naar rechts: de prijs daalt en het aanbod stijgt","er verandert niets"],"c":2,"d":3,"u":"Een subsidie maakt aanbieden goedkoper.","uo":["Nee, dat is het tegenovergestelde.","Nee, het werkt op het aanbod.","Klopt: een subsidie maakt aanbieden goedkoper.","Nee, er is wel effect."],"uh":"Subsidie: aanbod naar rechts, prijs daalt."},{"v":"Wat is het gevolg van een minimumprijs boven de evenwichtsprijs?","o":["de prijs daalt","er ontstaat een tekort","er verandert niets","er ontstaat een overschot: het aanbod overtreft de vraag"],"c":3,"d":3,"u":"Boven het evenwicht wordt meer aangeboden dan gevraagd.","uo":["Nee, de prijs mag juist niet lager.","Nee, een tekort hoort bij een maximumprijs.","Nee, er is wel effect.","Klopt: boven het evenwicht wordt meer aangeboden dan gevraagd."],"uh":"Minimumprijs boven evenwicht: overschot."},{"v":"Wat is inelastische vraag?","o":["vraag die nauwelijks reageert op een prijswijziging (|Ev| < 1)","vraag die sterk reageert op de prijs","vraag die naar nul daalt","vraag zonder aanbieders"],"c":0,"d":3,"u":"Inelastische vraag reageert zwak.","uo":["Klopt: inelastische vraag reageert zwak.","Nee, dat is elastisch.","Nee, dat is geen inelasticiteit.","Nee, dat gaat over aanbod."],"uh":"Inelastische vraag: reageert nauwelijks op de prijs."},{"v":"Wat is een meritgoed?","o":["een goed dat niemand wil","een goed dat de overheid stimuleert omdat er te weinig van wordt geproduceerd","een luxeproduct","een goed zonder prijs"],"c":1,"d":3,"u":"Bijvoorbeeld onderwijs of cultuur.","uo":["Nee, er is juist onderproductie van iets nuttigs.","Klopt: bijvoorbeeld onderwijs of cultuur.","Nee, dat hoeft niet.","Nee, dat is een vrij goed."],"uh":"Meritgoed: nuttig maar onderbenut, dus gestimuleerd."},{"v":"Bij een luxeproduct daalt de vraag sterk als de prijs stijgt. Welk begrip past hierbij?","o":["Extern effect","Oligopolie","Elastische vraag","Evenwichtsprijs"],"c":2,"d":1,"u":"Bij een luxeproduct daalt de vraag sterk als de prijs stijgt. Dat past bij Elastische vraag: sterke reactie op prijs.","uo":["Nee, dat hoort bij Extern effect: effect op derden buiten de prijs.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Klopt: sterke reactie op prijs.","Nee, dat hoort bij Evenwichtsprijs: vraag = aanbod."],"uh":"Elastische vraag: sterke reactie op prijs."},{"v":"Je betaalt minder dan je maximaal had willen betalen. Om welk begrip gaat het?","o":["Maximumprijs","Volkomen concurrentie","Evenwichtsprijs","Consumentensurplus"],"c":3,"d":1,"u":"Je betaalt minder dan je maximaal had willen betalen. Dat past bij Consumentensurplus: voordeel voor de consument.","uo":["Nee, dat hoort bij Maximumprijs: prijsplafond, tekort.","Nee, dat hoort bij Volkomen concurrentie: veel kleine aanbieders.","Nee, dat hoort bij Evenwichtsprijs: vraag = aanbod.","Klopt: voordeel voor de consument."],"uh":"Consumentensurplus: voordeel voor de consument."},{"v":"Het verschil tussen betalingsbereidheid en prijs. Welk begrip herken je hier?","o":["Consumentensurplus","Volkomen concurrentie","Evenwichtsprijs","Maximumprijs"],"c":0,"d":1,"u":"Het verschil tussen betalingsbereidheid en prijs. Dat past bij Consumentensurplus: voordeel voor de consument.","uo":["Klopt: voordeel voor de consument.","Nee, dat hoort bij Volkomen concurrentie: veel kleine aanbieders.","Nee, dat hoort bij Evenwichtsprijs: vraag = aanbod.","Nee, dat hoort bij Maximumprijs: prijsplafond, tekort."],"uh":"Consumentensurplus: voordeel voor de consument."},{"v":"Een goed dat de overheid stimuleert. Wat is hier aan de hand?","o":["Extern effect","Meritgoed","Evenwichtsprijs","Volkomen concurrentie"],"c":1,"d":1,"u":"Een goed dat de overheid stimuleert. Dat past bij Meritgoed: te weinig geproduceerd, gestimuleerd.","uo":["Nee, dat hoort bij Extern effect: effect op derden buiten de prijs.","Klopt: te weinig geproduceerd, gestimuleerd.","Nee, dat hoort bij Evenwichtsprijs: vraag = aanbod.","Nee, dat hoort bij Volkomen concurrentie: veel kleine aanbieders."],"uh":"Meritgoed: te weinig geproduceerd, gestimuleerd."},{"v":"De overheid subsidieert cultuur en onderwijs omdat er te weinig van komt. Welk begrip past hierbij?","o":["Extern effect","Maximumprijs","Meritgoed","Inelastische vraag"],"c":2,"d":2,"u":"De overheid subsidieert cultuur en onderwijs omdat er te weinig van komt. Dat past bij Meritgoed: te weinig geproduceerd, gestimuleerd.","uo":["Nee, dat hoort bij Extern effect: effect op derden buiten de prijs.","Nee, dat hoort bij Maximumprijs: prijsplafond, tekort.","Klopt: te weinig geproduceerd, gestimuleerd.","Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs."],"uh":"Meritgoed: te weinig geproduceerd, gestimuleerd."},{"v":"Een prijsbodem die een overschot veroorzaakt. Om welk begrip gaat het?","o":["Volkomen concurrentie","Inelastische vraag","Oligopolie","Minimumprijs"],"c":3,"d":1,"u":"Een prijsbodem die een overschot veroorzaakt. Dat past bij Minimumprijs: prijsbodem, overschot.","uo":["Nee, dat hoort bij Volkomen concurrentie: veel kleine aanbieders.","Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Klopt: prijsbodem, overschot."],"uh":"Minimumprijs: prijsbodem, overschot."},{"v":"Een prijsplafond dat een tekort veroorzaakt. Welk begrip herken je hier?","o":["Maximumprijs","Minimumprijs","Inelastische vraag","Elastische vraag"],"c":0,"d":2,"u":"Een prijsplafond dat een tekort veroorzaakt. Dat past bij Maximumprijs: prijsplafond, tekort.","uo":["Klopt: prijsplafond, tekort.","Nee, dat hoort bij Minimumprijs: prijsbodem, overschot.","Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Nee, dat hoort bij Elastische vraag: sterke reactie op prijs."],"uh":"Maximumprijs: prijsplafond, tekort."},{"v":"De overheid stelt een huurgrens onder de evenwichtsprijs in, met een tekort. Wat is hier aan de hand?","o":["Inelastische vraag","Maximumprijs","Oligopolie","Volkomen concurrentie"],"c":1,"d":1,"u":"De overheid stelt een huurgrens onder de evenwichtsprijs in, met een tekort. Dat past bij Maximumprijs: prijsplafond, tekort.","uo":["Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Klopt: prijsplafond, tekort.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Nee, dat hoort bij Volkomen concurrentie: veel kleine aanbieders."],"uh":"Maximumprijs: prijsplafond, tekort."},{"v":"Kosten of baten die derden treffen buiten de prijs. Welk begrip past hierbij?","o":["Elastische vraag","Oligopolie","Extern effect","Minimumprijs"],"c":2,"d":2,"u":"Kosten of baten die derden treffen buiten de prijs. Dat past bij Extern effect: effect op derden buiten de prijs.","uo":["Nee, dat hoort bij Elastische vraag: sterke reactie op prijs.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Klopt: effect op derden buiten de prijs.","Nee, dat hoort bij Minimumprijs: prijsbodem, overschot."],"uh":"Extern effect: effect op derden buiten de prijs."},{"v":"Fabrieksrook schaadt omwonenden die er niets mee te maken hebben. Om welk begrip gaat het?","o":["Inelastische vraag","Minimumprijs","Oligopolie","Extern effect"],"c":3,"d":1,"u":"Fabrieksrook schaadt omwonenden die er niets mee te maken hebben. Dat past bij Extern effect: effect op derden buiten de prijs.","uo":["Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Nee, dat hoort bij Minimumprijs: prijsbodem, overschot.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Klopt: effect op derden buiten de prijs."],"uh":"Extern effect: effect op derden buiten de prijs."},{"v":"Vraag die nauwelijks op de prijs reageert. Welk begrip herken je hier?","o":["Inelastische vraag","Elastische vraag","Oligopolie","Evenwichtsprijs"],"c":0,"d":2,"u":"Vraag die nauwelijks op de prijs reageert. Dat past bij Inelastische vraag: zwakke reactie op prijs.","uo":["Klopt: zwakke reactie op prijs.","Nee, dat hoort bij Elastische vraag: sterke reactie op prijs.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Nee, dat hoort bij Evenwichtsprijs: vraag = aanbod."],"uh":"Inelastische vraag: zwakke reactie op prijs."},{"v":"Een markt met veel kleine aanbieders. Wat is hier aan de hand?","o":["Extern effect","Volkomen concurrentie","Meritgoed","Minimumprijs"],"c":1,"d":1,"u":"Een markt met veel kleine aanbieders. Dat past bij Volkomen concurrentie: veel kleine aanbieders.","uo":["Nee, dat hoort bij Extern effect: effect op derden buiten de prijs.","Klopt: veel kleine aanbieders.","Nee, dat hoort bij Meritgoed: te weinig geproduceerd, gestimuleerd.","Nee, dat hoort bij Minimumprijs: prijsbodem, overschot."],"uh":"Volkomen concurrentie: veel kleine aanbieders."},{"v":"De prijs waar vraag en aanbod elkaar kruisen. Welk begrip past hierbij?","o":["Inelastische vraag","Maximumprijs","Evenwichtsprijs","Minimumprijs"],"c":2,"d":2,"u":"De prijs waar vraag en aanbod elkaar kruisen. Dat past bij Evenwichtsprijs: vraag = aanbod.","uo":["Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Nee, dat hoort bij Maximumprijs: prijsplafond, tekort.","Klopt: vraag = aanbod.","Nee, dat hoort bij Minimumprijs: prijsbodem, overschot."],"uh":"Evenwichtsprijs: vraag = aanbod."},{"v":"Een prijsbodem boven het evenwicht zorgt voor een overschot. Om welk begrip gaat het?","o":["Volkomen concurrentie","Inelastische vraag","Oligopolie","Minimumprijs"],"c":3,"d":1,"u":"Een prijsbodem boven het evenwicht zorgt voor een overschot. Dat past bij Minimumprijs: prijsbodem, overschot.","uo":["Nee, dat hoort bij Volkomen concurrentie: veel kleine aanbieders.","Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Klopt: prijsbodem, overschot."],"uh":"Minimumprijs: prijsbodem, overschot."},{"v":"Vraag die sterk reageert op de prijs. Welk begrip herken je hier?","o":["Elastische vraag","Inelastische vraag","Volkomen concurrentie","Maximumprijs"],"c":0,"d":2,"u":"Vraag die sterk reageert op de prijs. Dat past bij Elastische vraag: sterke reactie op prijs.","uo":["Klopt: sterke reactie op prijs.","Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Nee, dat hoort bij Volkomen concurrentie: veel kleine aanbieders.","Nee, dat hoort bij Maximumprijs: prijsplafond, tekort."],"uh":"Elastische vraag: sterke reactie op prijs."},{"v":"Een markt met weinig grote aanbieders. Wat is hier aan de hand?","o":["Extern effect","Oligopolie","Meritgoed","Elastische vraag"],"c":1,"d":1,"u":"Een markt met weinig grote aanbieders. Dat past bij Oligopolie: weinig grote aanbieders.","uo":["Nee, dat hoort bij Extern effect: effect op derden buiten de prijs.","Klopt: weinig grote aanbieders.","Nee, dat hoort bij Meritgoed: te weinig geproduceerd, gestimuleerd.","Nee, dat hoort bij Elastische vraag: sterke reactie op prijs."],"uh":"Oligopolie: weinig grote aanbieders."},{"v":"De prijs waarbij de gevraagde en aangeboden hoeveelheid precies gelijk zijn. Welk begrip past hierbij?","o":["Inelastische vraag","Maximumprijs","Evenwichtsprijs","Minimumprijs"],"c":2,"d":2,"u":"De prijs waarbij de gevraagde en aangeboden hoeveelheid precies gelijk zijn. Dat past bij Evenwichtsprijs: vraag = aanbod.","uo":["Nee, dat hoort bij Inelastische vraag: zwakke reactie op prijs.","Nee, dat hoort bij Maximumprijs: prijsplafond, tekort.","Klopt: vraag = aanbod.","Nee, dat hoort bij Minimumprijs: prijsbodem, overschot."],"uh":"Evenwichtsprijs: vraag = aanbod."},{"v":"Een paar grote supermarktketens houden elkaars prijzen in de gaten. Om welk begrip gaat het?","o":["Elastische vraag","Extern effect","Meritgoed","Oligopolie"],"c":3,"d":1,"u":"Een paar grote supermarktketens houden elkaars prijzen in de gaten. Dat past bij Oligopolie: weinig grote aanbieders.","uo":["Nee, dat hoort bij Elastische vraag: sterke reactie op prijs.","Nee, dat hoort bij Extern effect: effect op derden buiten de prijs.","Nee, dat hoort bij Meritgoed: te weinig geproduceerd, gestimuleerd.","Klopt: weinig grote aanbieders."],"uh":"Oligopolie: weinig grote aanbieders."},{"v":"Voor benzine blijft de vraag vrijwel gelijk, ook als de prijs stijgt. Welk begrip herken je hier?","o":["Inelastische vraag","Elastische vraag","Oligopolie","Evenwichtsprijs"],"c":0,"d":2,"u":"Voor benzine blijft de vraag vrijwel gelijk, ook als de prijs stijgt. Dat past bij Inelastische vraag: zwakke reactie op prijs.","uo":["Klopt: zwakke reactie op prijs.","Nee, dat hoort bij Elastische vraag: sterke reactie op prijs.","Nee, dat hoort bij Oligopolie: weinig grote aanbieders.","Nee, dat hoort bij Evenwichtsprijs: vraag = aanbod."],"uh":"Inelastische vraag: zwakke reactie op prijs."},{"v":"Op een groentemarkt verkopen veel kraampjes hetzelfde zonder prijsmacht. Wat is hier aan de hand?","o":["Extern effect","Volkomen concurrentie","Meritgoed","Minimumprijs"],"c":1,"d":1,"u":"Op een groentemarkt verkopen veel kraampjes hetzelfde zonder prijsmacht. Dat past bij Volkomen concurrentie: veel kleine aanbieders.","uo":["Nee, dat hoort bij Extern effect: effect op derden buiten de prijs.","Klopt: veel kleine aanbieders.","Nee, dat hoort bij Meritgoed: te weinig geproduceerd, gestimuleerd.","Nee, dat hoort bij Minimumprijs: prijsbodem, overschot."],"uh":"Volkomen concurrentie: veel kleine aanbieders."}],"oe":[{"bron":"Artikel","ctx":"De arbeidsmarkt verandert snel door technologische ontwikkelingen zoals automatisering en digitalisering. Veel routinematige banen verdwijnen of veranderen, terwijl nieuwe functies ontstaan in de IT-sector, zorg en techniek. Werkgevers hebben moeite om personeel te vinden met de juiste vaardigheden, waardoor tekorten ontstaan in cruciale sectoren. Tegelijkertijd groeit de groep flexwerkers, die minder zekerheden hebben maar meer vrijheid ervaren. Overheden proberen werknemers te stimuleren zich om te scholen, zodat zij beter kunnen inspelen op veranderingen. De dynamiek op de arbeidsmarkt laat zien hoe vraag en aanbod voortdurend verschuiven door economische en technologische ontwikkelingen.","v":"Leg uit hoe technologische ontwikkelingen kunnen leiden tot zowel werkloosheid als nieuwe werkgelegenheid.","o":[""],"c":0,"u":"Automatisering vervangt routinematige banen, waardoor werkloosheid kan ontstaan. Tegelijk ontstaan nieuwe banen in sectoren zoals IT en techniek. Werknemers moeten zich aanpassen aan nieuwe vaardigheden. Hierdoor verdwijnen sommige banen, maar komen er ook nieuwe bij."},{"bron":"Grafiek","ctx":"Grafiek-beschrijving: 'Staafdiagram met personeelstekorten in zorg, techniek en onderwijs tussen 2010 en 2025. Alle drie de sectoren laten een sterke stijging zien.'","v":"Leg uit waarom personeelstekorten vooral ontstaan in sectoren zoals zorg en techniek.","o":[""],"c":0,"u":"Deze sectoren vragen om specifieke vaardigheden. De opleidingstrajecten zijn lang en complex. Tegelijk groeit de vraag door vergrijzing en technologische ontwikkelingen. Hierdoor ontstaan structurele tekorten."},{"bron":"Artikel","ctx":"Productiviteit is een belangrijke factor voor economische groei. Wanneer werknemers meer produceren in dezelfde tijd, stijgt de totale output van een bedrijf. Innovatie, scholing en efficiënte werkprocessen dragen bij aan hogere productiviteit. Bedrijven investeren daarom in technologie en training om hun concurrentiepositie te versterken. Tegelijkertijd kan hoge werkdruk negatieve effecten hebben op motivatie en gezondheid, wat de productiviteit juist verlaagt. Een balans tussen efficiëntie en welzijn is daarom essentieel.","v":"Leg uit hoe scholing kan bijdragen aan hogere arbeidsproductiviteit.","o":[""],"c":0,"u":"Scholing zorgt ervoor dat werknemers nieuwe vaardigheden leren. Hierdoor kunnen zij efficiënter werken. Ook kunnen zij beter omgaan met nieuwe technologie. Dit verhoogt de productiviteit van het bedrijf. Scholing versterkt dus de concurrentiepositie."},{"bron":"Foto","ctx":"Foto-beschrijving: 'Productielijn in een fabriek waar robots en mensen samen werken aan assemblage.'","v":"Leg uit hoe automatisering de arbeidsproductiviteit beïnvloedt.","o":[""],"c":0,"u":"Automatisering neemt repetitieve taken over. Hierdoor kunnen werknemers zich richten op complexere taken. Robots werken snel en nauwkeurig, wat de productie verhoogt. De combinatie van mens en machine verhoogt de totale productiviteit."},{"bron":"Artikel","ctx":"De loonkosten spelen een grote rol in de concurrentiepositie van bedrijven. Wanneer lonen stijgen, worden producten duurder om te produceren. Bedrijven kunnen dit compenseren door efficiënter te werken of door prijzen te verhogen. In internationale markten kan een te hoge loonstijging leiden tot verlies van concurrentiekracht. Tegelijkertijd zijn hogere lonen belangrijk voor koopkracht en economische groei. De uitdaging is om een balans te vinden tussen betaalbare arbeid voor bedrijven en voldoende inkomen voor werknemers.","v":"Leg uit waarom te hoge loonkosten de concurrentiepositie van bedrijven kunnen verzwakken.","o":[""],"c":0,"u":"Hoge loonkosten maken productie duurder. Hierdoor moeten bedrijven hogere prijzen vragen. Dit maakt hen minder aantrekkelijk op internationale markten. Concurrenten met lagere kosten kunnen goedkoper produceren. Daarom verzwakken hoge loonkosten de concurrentiepositie."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 3)","ctx":"Het wettelijk minimumuurloon ligt boven het marktloon. De overheid verhoogt het minimumuurloon.","v":"Leg uit welk effect het verhogen van het minimumuurloon heeft op de werkloosheid.","o":[""],"c":0,"u":"Door het hogere minimumloon neemt het aanbod van arbeid toe en/of de gevraagde hoeveelheid arbeid af. Het overschot op de arbeidsmarkt (aanbod groter dan vraag) wordt groter, dus de werkloosheid neemt toe."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 8)","ctx":"Op Bonaire is een beperkt aantal fietsverhuurbedrijven actief. Ze verhuren gewone fietsen én speciale mountainbikes. De lokale bevolking gebruikt huurfietsen naast de eigen fiets.","v":"Vul aan: de fietsverhuurmarkt is een markt van (1: volkomen concurrentie / monopolistische concurrentie / oligopolie); de huurfietsen zijn (2: homogene / heterogene) producten; huurfietsen en eigen fietsen zijn (3: substitutie / complementaire) goederen.","o":[""],"c":0,"u":"(1) oligopolie - een beperkt aantal aanbieders. (2) heterogene - er zijn verschillende types (gewone fiets versus mountainbike). (3) substitutie - een huurfiets kan de eigen fiets vervangen."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 15)","ctx":"In het EU-emissiehandelssysteem krijgt elk bedrijf een hoeveelheid CO2-emissierechten. Wil een bedrijf meer uitstoten, dan moet het rechten kopen van een bedrijf dat minder uitstoot.","v":"Geef een verklaring waarom dit systeem bedrijven prikkelt om minder CO2 uit te stoten.","o":[""],"c":0,"u":"Meer uitstoten kost geld (rechten kopen), terwijl schoner produceren rechten bespaart die je kunt verkopen voor extra opbrengst. Beide geven een financiële prikkel om de uitstoot te verlagen."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 26)","ctx":"Verzekeraars gebruiken artificiële intelligentie om individuele risico’s te beoordelen en zo per verzekerde de premie vast te stellen.","v":"Geef een verklaring waarom de verzekeringsmarkt een markt van onvolkomen concurrentie is.","o":[""],"c":0,"u":"De aanbieder heeft invloed op de prijs: de verzekeraar stelt zelf de premie vast (prijszetter). Daarnaast ontbreekt transparantie doordat risico-inschattingen met AI per verzekeraar verschillen. Dat zijn kenmerken van onvolkomen concurrentie."},{"bron":"HAVO Economie CE 2024 Tijdvak 1 (vraag 5)","ctx":"De vraag naar goederen uit de supermarkt is prijsinelastisch. De prijzen in de supermarkt stijgen.","v":"Leg uit dat de prijsstijging van de supermarktgoederen leidt tot een stijging van de omzet.","o":[""],"c":0,"u":"Bij een prijsinelastische vraag daalt de afzet verhoudingsgewijs minder dan de prijs stijgt. Omdat omzet = prijs × afzet, stijgt de omzet bij een prijsstijging met een vrijwel gelijkblijvende afzet."},{"bron":"HAVO Economie CE 2024 Tijdvak 1 (vraag 7)","ctx":"Een speedpedelec is een snelle elektrische fiets. Bestuurders zijn verplicht een helm te dragen.","v":"Is een helm een substitutiegoed of een complementair goed van de speedpedelec? Geef een argument.","o":[""],"c":0,"u":"Complementair goed: de helm en de speedpedelec worden tegelijkertijd gebruikt, en de helm is zelfs verplicht bij het gebruik van de speedpedelec."},{"bron":"HAVO Economie CE 2024 Tijdvak 1 (vraag 8)","ctx":"De drie grootste aanbieders van speedpedelecs hebben samen 70% van de markt; elke aanbieder heeft keuzemogelijkheden in design, vermogen en accu. Voor één type zijn de marginale kosten constant: €3.500.","v":"Vul aan: de marktvorm is (1: volkomen concurrentie / monopolistische concurrentie / oligopolie); een speedpedelec is een (2: homogeen / heterogeen) goed; de variabele kosten zijn (3: proportioneel / progressief / degressief).","o":[""],"c":0,"u":"(1) oligopolie - enkele grote aanbieders met samen een groot marktaandeel. (2) heterogeen - de modellen verschillen in design, vermogen en accu. (3) proportioneel - de marginale kosten zijn constant, dus de variabele kosten stijgen evenredig met de productie."},{"bron":"HAVO Economie CE 2023 Tijdvak 1 (vraag 8)","ctx":"Door een tekort aan specialiteitenkoks dreigen de loonkosten op te lopen. De Wet arbeid vreemdelingen (WAV) stelt strenge voorwaarden aan het laten overkomen van koks uit Azië.","v":"Verklaar dat de WAV de opwaartse druk op de lonen van specialiteitenkoks laat bestaan.","o":[""],"c":0,"u":"De WAV beperkt de toename van het aanbod van specialiteitenkoks. Daardoor blijft het tekort op de arbeidsmarkt bestaan en blijven de lonen stijgen."},{"bron":"HAVO Economie CE 2023 Tijdvak 1 (vraag 11)","ctx":"De vereniging stelt dat het verhogen van het quotum aan buitenlandse koks de gemiddelde loonkosten van de restaurants kan laten dalen.","v":"Leg uit dat een daling van de gemiddelde loonkosten kan leiden tot een toename van de totale omzet van de restaurants.","o":[""],"c":0,"u":"Lagere gemiddelde loonkosten kunnen leiden tot een lagere prijs van de gerechten. Als de afzetstijging door die prijsverlaging relatief groter is dan de prijsdaling, neemt de totale omzet (prijs × afzet) per saldo toe."},{"bron":"HAVO Economie CE 2023 Tijdvak 1 (vraag 12)","ctx":"De sterke economische groei in Azië zorgt ervoor dat ook in Azië meer vraag naar koks ontstaat, waardoor minder koks naar Nederland komen.","v":"Vul aan: de vraag naar koks in Azië (1: daalt / stijgt); in de grafiek verschuift daardoor de (2: aanbodlijn / vraaglijn) naar (3: links / rechts); dit leidt tot een (4: afname / toename) van het totale surplus op de Nederlandse markt.","o":[""],"c":0,"u":"(1) stijgt. (2) de aanbodlijn (in Nederland). (3) naar links - er zijn minder koks beschikbaar. (4) afname van het totale surplus."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 1 (HA-1210-a-25-1-o)","ctx":"Supermarktbranche. Albert Heijn heeft een marktaandeel van 36% in Nederland. Jumbo heeft 22%. Er zijn nog enkele kleine spelers. Prijsafspraken zijn verboden.","v":"Noem de marktvorm en geef twee kenmerken die daarbij passen.","o":[""],"c":0,"u":"Oligopolie. Kenmerken: (1) Weinig aanbieders met groot marktaandeel. (2) Aanbieders zijn van elkaar afhankelijk (reactie op elkaars prijzen)."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 2 (HA-1210-a-25-1-o)","ctx":"De overheid legt een accijns van EUR 0,20 per liter benzine.","v":"(a) Verschuift de vraagcurve of de aanbodcurve? In welke richting?\n(b) Wat is het effect op het marktevenwicht?","o":[""],"c":0,"u":"(a) De aanbodcurve verschuift naar links/omhoog (hogere kosten voor aanbieders).\n(b) De evenwichtsprijs stijgt en de evenwichtshoeveelheid daalt."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 3 (HA-1210-a-25-1-o)","ctx":"Vraag: Qv = 200 - 2P. Aanbod: Qa = -40 + 3P.","v":"Bereken het marktevenwicht (evenwichtsprijs en -hoeveelheid).","o":[""],"c":0,"u":"200-2P = -40+3P\n240 = 5P\nP* = 48\nQ* = 200-2*48 = 104"},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 4 (HA-1210-a-25-1-o)","ctx":"Bij een prijsstijging van EUR 10 naar EUR 12 daalt de gevraagde hoeveelheid van 500 naar 400.","v":"Bereken de prijselasticiteit van de vraag en geef aan of de vraag elastisch of inelastisch is.","o":[""],"c":0,"u":"Ep = (%dQ / %dP) = ((-100/500) / (2/10)) = (-0,2 / 0,2) = -1\n|Ep| = 1 => neutraal elastisch."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 5 (HA-1210-a-25-1-o)","ctx":"ASML, fabrikant van chipmachines, is wereldwijd de enige die EUV-machines maakt.","v":"Welke marktvorm is dit? Noem twee nadelen van deze marktvorm voor de samenleving.","o":[""],"c":0,"u":"Monopolie. Nadelen: (1) Hogere prijs dan bij concurrentie (consumentenwelvaart daalt). (2) Minder productie dan maatschappelijk optimaal (welvaartverlies/deadweight loss)."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 6 (HA-1210-a-25-1-o)","ctx":"De overheid geeft EUR 2.000 subsidie per elektrische auto.","v":"Leg uit wat het directe effect is op de markt voor elektrische auto's.","o":[""],"c":0,"u":"De subsidie verlaagt de effectieve prijs voor kopers, waardoor de vraag toeneemt (vraagcurve verschuift naar rechts). De evenwichtsprijs daalt en de evenwichtshoeveelheid stijgt."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 14 (HA-1210-a-25-1-o)","ctx":"Een minimumuurloon van EUR 15 wordt ingesteld. Het evenwichtsloon is EUR 13.","v":"Leg uit welk effect dit heeft op de arbeidsmarkt.","o":[""],"c":0,"u":"Minimumprijs boven evenwicht: het arbeidsaanbod stijgt (meer mensen willen werken) maar de arbeidsvraag daalt (werkgevers vragen minder arbeid). Er ontstaat een overschot: werkloosheid neemt toe."}],"begrippen":[{"t":"Evenwichtsprijs","d":"de prijs waarbij de gevraagde en aangeboden hoeveelheid gelijk zijn"},{"t":"Elastische vraag","d":"vraag die sterk reageert op een prijsverandering (|Ev| > 1)"},{"t":"Inelastische vraag","d":"vraag die nauwelijks reageert op een prijsverandering (|Ev| < 1)"},{"t":"Extern effect","d":"kosten of baten van een transactie die derden treffen buiten de prijs"},{"t":"Oligopolie","d":"een markt met weinig grote aanbieders die elkaar in de gaten houden"},{"t":"Maximumprijs","d":"een prijsplafond onder het evenwicht, dat een tekort veroorzaakt"},{"t":"Minimumprijs","d":"een prijsbodem boven het evenwicht, die een overschot veroorzaakt"},{"t":"Consumentensurplus","d":"het verschil tussen betalingsbereidheid en betaalde prijs"},{"t":"Meritgoed","d":"een goed dat de overheid stimuleert omdat er te weinig van wordt geproduceerd"},{"t":"Volkomen concurrentie","d":"een markt met veel kleine aanbieders zonder prijsmacht"}],"sam":"<div class=\"sam-intro\">Op een markt ontstaat de <strong>evenwichtsprijs</strong> waar vraag en aanbod gelijk zijn. De <strong>prijselasticiteit</strong> geeft aan hoe sterk de vraag op de prijs reageert. <strong>Marktfalen</strong> ontstaat door <strong>externe effecten</strong> en <strong>collectieve goederen</strong>. De overheid grijpt in met een <strong>maximum-</strong> of <strong>minimumprijs</strong>.</div><div class=\"sam-head\">1. Vraag, aanbod en elasticiteit</div><p>De <strong>evenwichtsprijs</strong> is de prijs waarbij de gevraagde hoeveelheid gelijk is aan de aangeboden hoeveelheid. Bij <strong>elastische vraag</strong> (|Ev| > 1) reageert de vraag sterk op de prijs; bij <strong>inelastische vraag</strong> (|Ev| < 1) nauwelijks. Stijgt het inkomen, dan schuift de <strong>vraagcurve</strong> naar rechts. Het <strong>consumentensurplus</strong> is het verschil tussen betalingsbereidheid en betaalde prijs.</p><div class=\"sam-head\">2. Marktvormen en overheidsingrijpen</div><p>Van <strong>volkomen concurrentie</strong> (veel kleine aanbieders zonder prijsmacht) tot een <strong>oligopolie</strong> (weinig grote aanbieders) en een <strong>monopolie</strong> (één prijszetter). Een <strong>extern effect</strong> raakt derden buiten de prijs. Een <strong>maximumprijs</strong> onder het evenwicht geeft een tekort, een <strong>minimumprijs</strong> erboven een overschot. Een <strong>meritgoed</strong> stimuleert de overheid omdat er te weinig van wordt geproduceerd.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Evenwichtsprijs</div><div class=\"sam-definitie-body\">de prijs waarbij de gevraagde en aangeboden hoeveelheid gelijk zijn.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Elastische vraag</div><div class=\"sam-definitie-body\">vraag die sterk reageert op een prijsverandering (|Ev| &gt; 1).</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inelastische vraag</div><div class=\"sam-definitie-body\">vraag die nauwelijks reageert op een prijsverandering (|Ev| &lt; 1).</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Extern effect</div><div class=\"sam-definitie-body\">kosten of baten van een transactie die derden treffen buiten de prijs.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Oligopolie</div><div class=\"sam-definitie-body\">een markt met weinig grote aanbieders die elkaar in de gaten houden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Maximumprijs</div><div class=\"sam-definitie-body\">een prijsplafond onder het evenwicht, dat een tekort veroorzaakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Minimumprijs</div><div class=\"sam-definitie-body\">een prijsbodem boven het evenwicht, die een overschot veroorzaakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumentensurplus</div><div class=\"sam-definitie-body\">het verschil tussen betalingsbereidheid en betaalde prijs.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Meritgoed</div><div class=\"sam-definitie-body\">een goed dat de overheid stimuleert omdat er te weinig van wordt geproduceerd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Volkomen concurrentie</div><div class=\"sam-definitie-body\">een markt met veel kleine aanbieders zonder prijsmacht.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Evenwichtsprijs»</b> is vraag = aanbod, terwijl <b>«Maximumprijs»</b> prijsplafond, tekort is. <b>«Elastische vraag»</b> is sterke reactie op prijs, terwijl <b>«Inelastische vraag»</b> zwakke reactie op prijs is. <b>«Oligopolie»</b> is weinig grote aanbieders, terwijl <b>«Volkomen concurrentie»</b> veel kleine aanbieders is. <b>«Maximumprijs»</b> is prijsplafond, tekort, terwijl <b>«Minimumprijs»</b> prijsbodem, overschot is.</div>"},"D":{"sv":[{"v":"Welke drie functies heeft de overheid in de economie (Musgrave)?","o":["allocatie, herverdeling en stabilisatie","productie, handel en export","vraag, aanbod en prijs","sparen, lenen en beleggen"],"c":0,"d":3,"u":"Dat zijn de drie functies van Musgrave.","uo":["Klopt: dat zijn de drie functies van Musgrave.","Nee, dat is bedrijfsleven.","Nee, dat is de markt.","Nee, dat is de financiële sector."],"uh":"Musgrave: allocatie, herverdeling, stabilisatie."},{"v":"Welk type belasting wordt geheven op bestedingen in plaats van op inkomen of winst?","o":["directe belasting","indirecte belasting (zoals btw en accijns)","progressieve belasting","vermogensbelasting"],"c":1,"d":2,"u":"Btw en accijns zijn indirecte belastingen.","uo":["Nee, die zit op inkomen of winst.","Klopt: btw en accijns zijn indirecte belastingen.","Nee, dat gaat over het tarief.","Nee, dat zit op bezit."],"uh":"Indirecte belasting: op bestedingen (btw, accijns)."},{"v":"Wat is een progressief belastingstelsel?","o":["hoge inkomens betalen relatief minder","iedereen betaalt hetzelfde percentage","hoe hoger het inkomen, hoe hoger het belastingpercentage","niemand betaalt belasting"],"c":2,"d":2,"u":"Het tarief stijgt met het inkomen.","uo":["Nee, dat is degressief.","Nee, dat is proportioneel.","Klopt: het tarief stijgt met het inkomen.","Nee, er is wel belasting."],"uh":"Progressief: hoger inkomen, hoger percentage."},{"v":"Welk mechanisme stabiliseert de economie in een recessie zonder actief besluit?","o":["een handelsverdrag","een renteverhoging door de ECB","een nieuwe belastingwet","automatische stabilisatoren (zoals de WW)"],"c":3,"d":3,"u":"Uitkeringen lopen vanzelf op en dempen de klap.","uo":["Nee, dat is geen stabilisator.","Nee, dat is een actief besluit.","Nee, een wet is juist een besluit.","Klopt: uitkeringen lopen vanzelf op en dempen de klap."],"uh":"Automatische stabilisatoren: dempen vanzelf."},{"v":"Welke sociale zekerheid wordt uit premies betaald en geeft recht op uitkering bij werkloosheid?","o":["een sociale verzekering","een sociale voorziening","een subsidie","een toeslag"],"c":0,"d":3,"u":"Verzekeringen worden uit premies gefinancierd.","uo":["Klopt: verzekeringen worden uit premies gefinancierd.","Nee, die komt uit belasting.","Nee, dat is iets anders.","Nee, dat is iets anders."],"uh":"Sociale verzekering: uit premies."},{"v":"Wat is de herverdelingsfunctie van de overheid?","o":["collectieve goederen leveren","inkomensongelijkheid verkleinen via belasting en uitkeringen","de conjunctuur dempen","de rente vaststellen"],"c":1,"d":2,"u":"Herverdeling verkleint de ongelijkheid.","uo":["Nee, dat is allocatie.","Klopt: herverdeling verkleint de ongelijkheid.","Nee, dat is stabilisatie.","Nee, dat doet de ECB."],"uh":"Herverdeling: ongelijkheid verkleinen."},{"v":"Wat is het verschil tussen directe en indirecte belasting?","o":["direct is op bestedingen","ze zijn hetzelfde","direct is op inkomen of winst, indirect op bestedingen","indirect is op inkomen"],"c":2,"d":3,"u":"Inkomen/winst tegenover bestedingen.","uo":["Nee, dat is omgedraaid.","Nee, ze verschillen.","Klopt: inkomen/winst tegenover bestedingen.","Nee, dat is omgedraaid."],"uh":"Direct: inkomen/winst; indirect: bestedingen."},{"v":"Wat is de armoedeval?","o":["de belasting is te laag","sparen levert niets op","de prijzen stijgen te snel","werken loont financieel niet doordat toeslagen wegvallen"],"c":3,"d":3,"u":"Meer verdienen levert netto weinig op door verlies van toeslagen.","uo":["Nee, dat is niet de armoedeval.","Nee, dat gaat over sparen.","Nee, dat is inflatie.","Klopt: meer verdienen levert netto weinig op door verlies van toeslagen."],"uh":"Armoedeval: werken loont niet door wegvallende toeslagen."},{"v":"Wat is een begrotingstekort?","o":["de overheidsuitgaven zijn groter dan de inkomsten in een jaar","de overheid houdt geld over","de staatsschuld is afgelost","de belasting is verlaagd"],"c":0,"d":2,"u":"Meer uitgaven dan inkomsten in één jaar.","uo":["Klopt: meer uitgaven dan inkomsten in één jaar.","Nee, dat is een overschot.","Nee, dat is iets anders.","Nee, dat is geen tekort."],"uh":"Begrotingstekort: uitgaven > inkomsten in een jaar."},{"v":"Wat is de collectieve lastendruk?","o":["de totale staatsschuld","belastingen en sociale premies als percentage van het bbp","het begrotingstekort","de rente op leningen"],"c":1,"d":3,"u":"Het aandeel van belasting en premies in het bbp.","uo":["Nee, dat is de schuld.","Klopt: het aandeel van belasting en premies in het bbp.","Nee, dat is het jaarlijkse tekort.","Nee, dat is rente."],"uh":"Collectieve lastendruk: belasting + premies als % bbp."},{"v":"Wat is de staatsschuld?","o":["de totale belasting van een jaar","het tekort van één jaar","de som van alle historische tekorten minus de overschotten","de rente van dit jaar"],"c":2,"d":3,"u":"Alle opgetelde tekorten vormen de schuld.","uo":["Nee, dat is de belastingopbrengst.","Nee, dat is het begrotingstekort.","Klopt: alle opgetelde tekorten vormen de schuld.","Nee, dat is de rentelast."],"uh":"Staatsschuld: opgetelde tekorten min overschotten."},{"v":"Welke maatregel hoort bij keynesiaans conjunctuurbeleid tijdens een recessie?","o":["niets doen","belasting verhogen en bezuinigen","de rente door de overheid verhogen","belasting verlagen en meer uitgeven om de vraag te stimuleren"],"c":3,"d":3,"u":"Keynes wil de vraag aanjagen in een recessie.","uo":["Nee, Keynes pleit voor ingrijpen.","Nee, dat remt juist af.","Nee, de rente is monetair beleid.","Klopt: Keynes wil de vraag aanjagen in een recessie."],"uh":"Keynes in recessie: stimuleren (minder belasting, meer uitgeven)."},{"v":"Waarom werkt btw regressief voor lagere inkomens?","o":["lage inkomens besteden een groter deel van hun geld, dus btw weegt zwaarder","lage inkomens betalen een hoger btw-tarief","btw geldt alleen voor lage inkomens","btw is een directe belasting"],"c":0,"d":3,"u":"Wie alles uitgeeft, betaalt relatief meer btw.","uo":["Klopt: wie alles uitgeeft, betaalt relatief meer btw.","Nee, het tarief is voor iedereen gelijk.","Nee, btw geldt voor iedereen.","Nee, btw is indirect."],"uh":"Btw regressief: lage inkomens besteden relatief meer."},{"v":"Via belasting en uitkeringen verkleint de overheid de inkomensverschillen. Welk begrip past hierbij?","o":["Sociale verzekering","Herverdelingsfunctie","Progressief belastingstelsel","Indirecte belasting"],"c":1,"d":1,"u":"Via belasting en uitkeringen verkleint de overheid de inkomensverschillen. Dat past bij Herverdelingsfunctie: ongelijkheid verkleinen.","uo":["Nee, dat hoort bij Sociale verzekering: uit premies.","Klopt: ongelijkheid verkleinen.","Nee, dat hoort bij Progressief belastingstelsel: hoger inkomen, hoger percentage.","Nee, dat hoort bij Indirecte belasting: op bestedingen."],"uh":"Herverdelingsfunctie: ongelijkheid verkleinen."},{"v":"De overheid geeft in een jaar meer uit dan ze binnenkrijgt. Om welk begrip gaat het?","o":["Herverdelingsfunctie","Stabilisatiefunctie","Begrotingstekort","Allocatiefunctie"],"c":2,"d":1,"u":"De overheid geeft in een jaar meer uit dan ze binnenkrijgt. Dat past bij Begrotingstekort: uitgaven > inkomsten.","uo":["Nee, dat hoort bij Herverdelingsfunctie: ongelijkheid verkleinen.","Nee, dat hoort bij Stabilisatiefunctie: conjunctuur dempen.","Klopt: uitgaven > inkomsten.","Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren."],"uh":"Begrotingstekort: uitgaven > inkomsten."},{"v":"Uitgaven groter dan inkomsten in een jaar. Welk begrip herken je hier?","o":["Allocatiefunctie","Stabilisatiefunctie","Herverdelingsfunctie","Begrotingstekort"],"c":3,"d":1,"u":"Uitgaven groter dan inkomsten in een jaar. Dat past bij Begrotingstekort: uitgaven > inkomsten.","uo":["Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren.","Nee, dat hoort bij Stabilisatiefunctie: conjunctuur dempen.","Nee, dat hoort bij Herverdelingsfunctie: ongelijkheid verkleinen.","Klopt: uitgaven > inkomsten."],"uh":"Begrotingstekort: uitgaven > inkomsten."},{"v":"De som van alle historische tekorten. Wat is hier aan de hand?","o":["Staatsschuld","Stabilisatiefunctie","Indirecte belasting","Sociale verzekering"],"c":0,"d":1,"u":"De som van alle historische tekorten. Dat past bij Staatsschuld: opgetelde tekorten.","uo":["Klopt: opgetelde tekorten.","Nee, dat hoort bij Stabilisatiefunctie: conjunctuur dempen.","Nee, dat hoort bij Indirecte belasting: op bestedingen.","Nee, dat hoort bij Sociale verzekering: uit premies."],"uh":"Staatsschuld: opgetelde tekorten."},{"v":"Alle tekorten van vroeger bij elkaar opgeteld. Welk begrip past hierbij?","o":["Stabilisatiefunctie","Staatsschuld","Indirecte belasting","Sociale verzekering"],"c":1,"d":1,"u":"Alle tekorten van vroeger bij elkaar opgeteld. Dat past bij Staatsschuld: opgetelde tekorten.","uo":["Nee, dat hoort bij Stabilisatiefunctie: conjunctuur dempen.","Klopt: opgetelde tekorten.","Nee, dat hoort bij Indirecte belasting: op bestedingen.","Nee, dat hoort bij Sociale verzekering: uit premies."],"uh":"Staatsschuld: opgetelde tekorten."},{"v":"Mechanismen die de economie vanzelf dempen. Om welk begrip gaat het?","o":["Allocatiefunctie","Staatsschuld","Automatische stabilisatoren","Directe belasting"],"c":2,"d":2,"u":"Mechanismen die de economie vanzelf dempen. Dat past bij Automatische stabilisatoren: dempen vanzelf.","uo":["Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren.","Nee, dat hoort bij Staatsschuld: opgetelde tekorten.","Klopt: dempen vanzelf.","Nee, dat hoort bij Directe belasting: op inkomen of winst."],"uh":"Automatische stabilisatoren: dempen vanzelf."},{"v":"Hoger inkomen, hoger percentage. Welk begrip herken je hier?","o":["Allocatiefunctie","Directe belasting","Staatsschuld","Progressief belastingstelsel"],"c":3,"d":1,"u":"Hoger inkomen, hoger percentage. Dat past bij Progressief belastingstelsel: hoger inkomen, hoger percentage.","uo":["Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren.","Nee, dat hoort bij Directe belasting: op inkomen of winst.","Nee, dat hoort bij Staatsschuld: opgetelde tekorten.","Klopt: hoger inkomen, hoger percentage."],"uh":"Progressief belastingstelsel: hoger inkomen, hoger percentage."},{"v":"Wie meer verdient, betaalt een hoger belastingpercentage. Wat is hier aan de hand?","o":["Progressief belastingstelsel","Herverdelingsfunctie","Indirecte belasting","Allocatiefunctie"],"c":0,"d":2,"u":"Wie meer verdient, betaalt een hoger belastingpercentage. Dat past bij Progressief belastingstelsel: hoger inkomen, hoger percentage.","uo":["Klopt: hoger inkomen, hoger percentage.","Nee, dat hoort bij Herverdelingsfunctie: ongelijkheid verkleinen.","Nee, dat hoort bij Indirecte belasting: op bestedingen.","Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren."],"uh":"Progressief belastingstelsel: hoger inkomen, hoger percentage."},{"v":"Belasting op inkomen of winst. Welk begrip past hierbij?","o":["Begrotingstekort","Directe belasting","Herverdelingsfunctie","Staatsschuld"],"c":1,"d":1,"u":"Belasting op inkomen of winst. Dat past bij Directe belasting: op inkomen of winst.","uo":["Nee, dat hoort bij Begrotingstekort: uitgaven > inkomsten.","Klopt: op inkomen of winst.","Nee, dat hoort bij Herverdelingsfunctie: ongelijkheid verkleinen.","Nee, dat hoort bij Staatsschuld: opgetelde tekorten."],"uh":"Directe belasting: op inkomen of winst."},{"v":"Loonbelasting en winstbelasting zitten op inkomen en winst. Om welk begrip gaat het?","o":["Progressief belastingstelsel","Indirecte belasting","Directe belasting","Sociale verzekering"],"c":2,"d":2,"u":"Loonbelasting en winstbelasting zitten op inkomen en winst. Dat past bij Directe belasting: op inkomen of winst.","uo":["Nee, dat hoort bij Progressief belastingstelsel: hoger inkomen, hoger percentage.","Nee, dat hoort bij Indirecte belasting: op bestedingen.","Klopt: op inkomen of winst.","Nee, dat hoort bij Sociale verzekering: uit premies."],"uh":"Directe belasting: op inkomen of winst."},{"v":"De overheid dempt de conjunctuur. Welk begrip herken je hier?","o":["Begrotingstekort","Directe belasting","Automatische stabilisatoren","Stabilisatiefunctie"],"c":3,"d":1,"u":"De overheid dempt de conjunctuur. Dat past bij Stabilisatiefunctie: conjunctuur dempen.","uo":["Nee, dat hoort bij Begrotingstekort: uitgaven > inkomsten.","Nee, dat hoort bij Directe belasting: op inkomen of winst.","Nee, dat hoort bij Automatische stabilisatoren: dempen vanzelf.","Klopt: conjunctuur dempen."],"uh":"Stabilisatiefunctie: conjunctuur dempen."},{"v":"Sociale zekerheid uit premies. Wat is hier aan de hand?","o":["Sociale verzekering","Automatische stabilisatoren","Allocatiefunctie","Stabilisatiefunctie"],"c":0,"d":2,"u":"Sociale zekerheid uit premies. Dat past bij Sociale verzekering: uit premies.","uo":["Klopt: uit premies.","Nee, dat hoort bij Automatische stabilisatoren: dempen vanzelf.","Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren.","Nee, dat hoort bij Stabilisatiefunctie: conjunctuur dempen."],"uh":"Sociale verzekering: uit premies."},{"v":"De overheid levert wat de markt niet voortbrengt. Welk begrip past hierbij?","o":["Indirecte belasting","Allocatiefunctie","Directe belasting","Stabilisatiefunctie"],"c":1,"d":1,"u":"De overheid levert wat de markt niet voortbrengt. Dat past bij Allocatiefunctie: collectieve goederen leveren.","uo":["Nee, dat hoort bij Indirecte belasting: op bestedingen.","Klopt: collectieve goederen leveren.","Nee, dat hoort bij Directe belasting: op inkomen of winst.","Nee, dat hoort bij Stabilisatiefunctie: conjunctuur dempen."],"uh":"Allocatiefunctie: collectieve goederen leveren."},{"v":"In een recessie lopen de WW-uitgaven vanzelf op en dempen de klap. Om welk begrip gaat het?","o":["Allocatiefunctie","Staatsschuld","Automatische stabilisatoren","Directe belasting"],"c":2,"d":2,"u":"In een recessie lopen de WW-uitgaven vanzelf op en dempen de klap. Dat past bij Automatische stabilisatoren: dempen vanzelf.","uo":["Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren.","Nee, dat hoort bij Staatsschuld: opgetelde tekorten.","Klopt: dempen vanzelf.","Nee, dat hoort bij Directe belasting: op inkomen of winst."],"uh":"Automatische stabilisatoren: dempen vanzelf."},{"v":"De overheid verkleint de inkomensongelijkheid. Welk begrip herken je hier?","o":["Indirecte belasting","Sociale verzekering","Progressief belastingstelsel","Herverdelingsfunctie"],"c":3,"d":1,"u":"De overheid verkleint de inkomensongelijkheid. Dat past bij Herverdelingsfunctie: ongelijkheid verkleinen.","uo":["Nee, dat hoort bij Indirecte belasting: op bestedingen.","Nee, dat hoort bij Sociale verzekering: uit premies.","Nee, dat hoort bij Progressief belastingstelsel: hoger inkomen, hoger percentage.","Klopt: ongelijkheid verkleinen."],"uh":"Herverdelingsfunctie: ongelijkheid verkleinen."},{"v":"Belasting op bestedingen. Wat is hier aan de hand?","o":["Indirecte belasting","Directe belasting","Allocatiefunctie","Automatische stabilisatoren"],"c":0,"d":2,"u":"Belasting op bestedingen. Dat past bij Indirecte belasting: op bestedingen.","uo":["Klopt: op bestedingen.","Nee, dat hoort bij Directe belasting: op inkomen of winst.","Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren.","Nee, dat hoort bij Automatische stabilisatoren: dempen vanzelf."],"uh":"Indirecte belasting: op bestedingen."},{"v":"De overheid legt wegen aan en zorgt voor defensie: collectieve goederen. Welk begrip past hierbij?","o":["Herverdelingsfunctie","Allocatiefunctie","Sociale verzekering","Stabilisatiefunctie"],"c":1,"d":3,"u":"De overheid legt wegen aan en zorgt voor defensie: collectieve goederen. Dat past bij Allocatiefunctie: collectieve goederen leveren.","uo":["Nee, dat hoort bij Herverdelingsfunctie: ongelijkheid verkleinen.","Klopt: collectieve goederen leveren.","Nee, dat hoort bij Sociale verzekering: uit premies.","Nee, dat hoort bij Stabilisatiefunctie: conjunctuur dempen."],"uh":"Allocatiefunctie: collectieve goederen leveren."},{"v":"Btw en accijns zitten op wat je koopt. Om welk begrip gaat het?","o":["Automatische stabilisatoren","Herverdelingsfunctie","Indirecte belasting","Begrotingstekort"],"c":2,"d":1,"u":"Btw en accijns zitten op wat je koopt. Dat past bij Indirecte belasting: op bestedingen.","uo":["Nee, dat hoort bij Automatische stabilisatoren: dempen vanzelf.","Nee, dat hoort bij Herverdelingsfunctie: ongelijkheid verkleinen.","Klopt: op bestedingen.","Nee, dat hoort bij Begrotingstekort: uitgaven > inkomsten."],"uh":"Indirecte belasting: op bestedingen."},{"v":"In een recessie stimuleert de overheid, in een hausse remt ze af. Welk begrip herken je hier?","o":["Automatische stabilisatoren","Allocatiefunctie","Herverdelingsfunctie","Stabilisatiefunctie"],"c":3,"d":2,"u":"In een recessie stimuleert de overheid, in een hausse remt ze af. Dat past bij Stabilisatiefunctie: conjunctuur dempen.","uo":["Nee, dat hoort bij Automatische stabilisatoren: dempen vanzelf.","Nee, dat hoort bij Allocatiefunctie: collectieve goederen leveren.","Nee, dat hoort bij Herverdelingsfunctie: ongelijkheid verkleinen.","Klopt: conjunctuur dempen."],"uh":"Stabilisatiefunctie: conjunctuur dempen."},{"v":"De WW wordt uit premies van werkenden betaald. Wat is hier aan de hand?","o":["Sociale verzekering","Indirecte belasting","Directe belasting","Automatische stabilisatoren"],"c":0,"d":3,"u":"De WW wordt uit premies van werkenden betaald. Dat past bij Sociale verzekering: uit premies.","uo":["Klopt: uit premies.","Nee, dat hoort bij Indirecte belasting: op bestedingen.","Nee, dat hoort bij Directe belasting: op inkomen of winst.","Nee, dat hoort bij Automatische stabilisatoren: dempen vanzelf."],"uh":"Sociale verzekering: uit premies."}],"oe":[{"bron":"Artikel","ctx":"De overheid speelt een belangrijke rol in het functioneren van markten. Door belastingen, subsidies en regelgeving probeert zij marktfalen te voorkomen. Een bekend voorbeeld is milieuschade: bedrijven houden in hun prijzen geen rekening met de negatieve effecten van vervuiling. De overheid kan dit corrigeren door vervuilende activiteiten te belasten of duurzame alternatieven te subsidiëren. Ook bij monopolies grijpt de overheid in om consumenten te beschermen tegen te hoge prijzen. Daarnaast zorgt zij voor publieke goederen zoals straatverlichting en dijken, die niet door de markt worden geleverd. Overheidsingrijpen is dus essentieel om markten eerlijk en efficiënt te laten functioneren.","v":"Leg uit waarom de overheid ingrijpt bij negatieve externe effecten.","o":[""],"c":0,"u":"Negatieve externe effecten worden niet meegenomen in de marktprijs. Hierdoor ontstaat overproductie van vervuilende activiteiten. De overheid corrigeert dit met belastingen of regels. Zo worden de maatschappelijke kosten beter verdeeld. Dit zorgt voor een efficiëntere markt."},{"bron":"Grafiek","ctx":"Grafiek-beschrijving: 'Aanbod- en vraagcurve met een minimumprijs boven het evenwicht, waardoor een aanbodoverschot ontstaat.'","v":"Leg uit waarom een minimumprijs kan leiden tot een aanbodoverschot.","o":[""],"c":0,"u":"Een minimumprijs ligt boven de evenwichtsprijs. Hierdoor willen producenten meer aanbieden. Consumenten kopen echter minder door de hogere prijs. Het verschil tussen aanbod en vraag vormt een overschot. Dit is een direct gevolg van prijsregulering."},{"bron":"Artikel","ctx":"Belastingen zijn een belangrijk instrument voor de overheid om inkomsten te genereren en gedrag te beïnvloeden. Accijnzen op tabak en alcohol moeten consumptie ontmoedigen, terwijl btw een brede belasting is op consumptie. De hoogte van belastingen beïnvloedt het besteedbaar inkomen van huishoudens. Wanneer belastingen stijgen, daalt de koopkracht, wat gevolgen heeft voor de totale vraag in de economie. Tegelijk gebruikt de overheid belastinginkomsten om publieke voorzieningen te financieren, zoals onderwijs, zorg en infrastructuur.","v":"Leg uit hoe hogere belastingen de koopkracht van huishoudens beïnvloeden.","o":[""],"c":0,"u":"Hogere belastingen verlagen het besteedbaar inkomen. Huishoudens kunnen daardoor minder goederen en diensten kopen. Dit vermindert hun koopkracht. De totale vraag in de economie kan hierdoor dalen. Belastingen hebben dus directe invloed op consumptie."},{"bron":"Foto","ctx":"Foto-beschrijving: 'Een marktplein met verschillende kraampjes en een bord waarop staat: 'Subsidie op duurzame producten'.'","v":"Leg uit hoe subsidies de marktuitkomst kunnen beïnvloeden.","o":[""],"c":0,"u":"Subsidies verlagen de prijs voor consumenten. Hierdoor stijgt de vraag naar duurzame producten. Producenten worden gestimuleerd om meer te produceren. De markt verschuift richting duurzamere keuzes. Subsidies corrigeren zo marktfalen."},{"bron":"Artikel","ctx":"Monopolies kunnen ontstaan wanneer één bedrijf een groot marktaandeel heeft of wanneer toetreding tot de markt moeilijk is. Dit kan leiden tot hoge prijzen en weinig innovatie. De overheid houdt toezicht via mededingingsautoriteiten die kartels opsporen en fusies beoordelen. Door concurrentie te stimuleren probeert de overheid markten efficiënt te houden. In sommige sectoren, zoals energie en spoorwegen, blijft regulering noodzakelijk omdat natuurlijke monopolies moeilijk te vermijden zijn.","v":"Leg uit waarom de overheid toezicht houdt op monopolies.","o":[""],"c":0,"u":"Monopolies kunnen te hoge prijzen vragen. Consumenten hebben dan weinig keuze. Ook kan innovatie afnemen door gebrek aan concurrentie. De overheid beschermt consumenten door toezicht te houden. Zo blijft de markt eerlijker en efficiënter."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 16)","ctx":"Pay-offmatrix winstverandering (in miljoen euro, als Gas ; Kolen). Beide bedrijven kiezen tussen \"emissierechten kopen\" en \"investeren in duurzame productie\". Uitkomsten: beiden kopen −70 ; −80. Gas koopt, Kolen investeert −50 ; −40. Gas investeert, Kolen koopt −30 ; −60. Beiden investeren −35 ; −45.","v":"Leg uit of beide bedrijven in een gevangenendilemma terechtkomen (bepaal eerst de dominante strategie van beide bedrijven).","o":[""],"c":0,"u":"Gas investeert altijd: −30 > −70 en −35 > −50. Kolen investeert altijd: −40 > −80 en −45 > −60. De uitkomst is dus (−35 ; −45): beiden investeren. Dat is meteen de best mogelijke gezamenlijke uitkomst, dus er is GEEN gevangenendilemma (bij een gevangenendilemma is het evenwicht juist slechter dan samenwerken)."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 21)","ctx":"De AOW is een basispensioen voor ouderen. De premies die werkenden nu betalen, worden gebruikt om de AOW-uitkeringen in datzelfde jaar te betalen.","v":"Wordt de AOW gefinancierd volgens het kapitaaldekkingsstelsel of het omslagstelsel? Motiveer je keuze.","o":[""],"c":0,"u":"Omslagstelsel: de premies die de werkenden van nu betalen, financieren direct de AOW-uitkeringen van de huidige AOW’ers in hetzelfde jaar. Er wordt geen eigen kapitaal opgebouwd."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 27)","ctx":"Verzekeraars zetten artificiële intelligentie in om premies te personaliseren op basis van het individuele risicoprofiel van verzekerden.","v":"Leg uit dat dit kan leiden tot een afname van averechtse selectie.","o":[""],"c":0,"u":"Goede (lage) risico’s krijgen een lagere premie en blijven zich daardoor verzekeren in plaats van af te haken. Zo blijven er in verhouding meer goede risico’s in de verzekering, waardoor averechtse selectie afneemt."},{"bron":"HAVO Economie CE 2024 Tijdvak 1 (vraag 1)","ctx":"De vakbond eist 3,5% loonsverhoging met een minimale stijging van €1.000. De nieuwe cao geldt voor alle werknemers.","v":"Leg uit dat er sprake is van nivelleren als deze looneis wordt ingewilligd.","o":[""],"c":0,"u":"Door het bodembedrag van €1.000 krijgen de lagere inkomens (onder €28.571 = 1.000 / 0,035) procentueel méér dan 3,5%, terwijl de hogere inkomens precies 3,5% krijgen. De relatieve inkomensverschillen worden zo kleiner - dat is nivelleren."},{"bron":"HAVO Economie CE 2024 Tijdvak 1 (vraag 11)","ctx":"Bij een onderhandeling doet de ene partij een voorstel om een geldbedrag te verdelen; de andere partij accepteert of weigert. Bij weigeren krijgen beide partijen niets. Dit is een ultimatumspel.","v":"Vul aan: een ultimatumspel is een (1: sequentieel / simultaan) spel met (2: twee / drie) spelers; de (3: aanbieder / respondent) doet een voorstel, de (4: aanbieder / respondent) accepteert of weigert; bij (5: accepteren / weigeren) krijgen beide hun deel.","o":[""],"c":0,"u":"(1) sequentieel - de spelers kiezen na elkaar. (2) twee spelers. (3) de aanbieder doet het voorstel. (4) de respondent reageert. (5) accepteren - alleen dan ontvangen beide hun deel."},{"bron":"HAVO Economie CE 2024 Tijdvak 1 (vraag 14)","ctx":"In een ultimatumspel doet Snel een laag bod aan Sprinter. De praktijk leert dat zulke lage biedingen vaak worden geweigerd, ook al krijgen beide partijen dan niets.","v":"Geef een reden waarom Sprinter het lage prijsvoorstel toch zou weigeren.","o":[""],"c":0,"u":"Bijvoorbeeld: Sprinter heeft een afkeer van ongelijkheid en vindt de verdeling oneerlijk, of wil Snel straffen voor het oneerlijke bod - ook al kost het Sprinter zelf de opbrengst."},{"bron":"HAVO Economie CE 2023 Tijdvak 1 (vraag 1)","ctx":"Werknemers in loondienst zijn verplicht verzekerd tegen arbeidsongeschiktheid; de premies betalen de uitkeringen in datzelfde jaar. Zzp’ers moeten zich individueel verzekeren (aov), wat in de praktijk duurder is.","v":"Vul aan: de verzekering voor werknemers is een (1: particuliere / sociale) verzekering via het (2: kapitaaldekkingsstelsel / omslagstelsel). Bij een individuele aov ontbreekt (3: asymmetrische informatie / collectieve dwang / intertemporele ruil), waardoor er sprake is van (4: averechtse selectie / meeliftgedrag / verzonken kosten) en de premie relatief hoog is.","o":[""],"c":0,"u":"(1) sociale verzekering (verplicht voor werknemers). (2) omslagstelsel - de premies betalen de uitkeringen van datzelfde jaar. (3) collectieve dwang ontbreekt bij een individuele aov. (4) averechtse selectie - vooral mensen met een hoog risico verzekeren zich, waardoor de premie hoog wordt."},{"bron":"HAVO Economie CE 2023 Tijdvak 1 (vraag 4)","ctx":"Een vakbondslid stelt dat arbeidsongeschiktheid kan leiden tot denivellering van de secundaire inkomens tussen arbeidsongeschikte zzp’ers en arbeidsongeschikte werknemers uit dezelfde inkomensklasse.","v":"Leg deze stelling uit.","o":[""],"c":0,"u":"Werknemers zijn verplicht verzekerd en krijgen bij arbeidsongeschiktheid een uitkering, terwijl een deel van de zzp’ers niet verzekerd is en dus een groter secundair inkomensverlies lijdt. Het inkomensverschil tussen beide groepen wordt daardoor groter: denivellering."},{"bron":"HAVO Economie CE 2023 Tijdvak 1 (vraag 7)","ctx":"Aziatische restaurants hebben een tekort aan specialiteitenkoks. Omscholingstrajecten van Nederlandse koks hebben nog geen koks opgeleverd die op het vereiste niveau werken.","v":"Leg uit dat bij de investering in omscholingstrajecten sprake is van verzonken kosten voor de sector.","o":[""],"c":0,"u":"Als de omgeschoolde koks het vereiste niveau niet halen, kunnen ze niet als specialiteitenkok worden ingezet. De investeringskosten van de scholing zijn dan op geen enkele andere manier terug te verdienen - dat zijn verzonken kosten."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 13 (HA-1210-a-25-1-o)","ctx":"De overheid verlaagt de inkomstenbelasting voor de laagste inkomensgroepen.","v":"Leg uit of dit een automatisch stabilisator of een discretionair beleid is, en wat het verwachte effect is op de conjunctuur.","o":[""],"c":0,"u":"Discretionair beleid: bewuste overheidsbeslissing. Lagere belasting verhoogt besteedbaar inkomen, vergroot consumptie en stimuleert economische groei (expansief fiscaal beleid)."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 15 (HA-1210-a-25-1-o)","ctx":"Externe effecten.","v":"Leg uit wat een negatief extern effect is en geef een beleidsmaatregel van de overheid om dit te corrigeren.","o":[""],"c":0,"u":"Negatief extern effect: kosten van productie worden afgewenteld op derden (bijv. luchtvervuiling door fabriek). Maatregel: heffing/belasting gelijk aan de externe kosten (Pigouviaanse belasting), waarna de producent de volledige maatschappelijke kosten draagt."}],"begrippen":[{"t":"Allocatiefunctie","d":"de overheid levert collectieve goederen die de markt niet voortbrengt"},{"t":"Herverdelingsfunctie","d":"inkomensongelijkheid verkleinen via belasting en uitkeringen"},{"t":"Stabilisatiefunctie","d":"conjunctuurschommelingen dempen door te stimuleren of af te remmen"},{"t":"Directe belasting","d":"belasting op inkomen of winst"},{"t":"Indirecte belasting","d":"belasting op bestedingen, zoals btw en accijns"},{"t":"Progressief belastingstelsel","d":"hoe hoger het inkomen, hoe hoger het belastingpercentage"},{"t":"Automatische stabilisatoren","d":"mechanismen die de economie vanzelf dempen, zonder nieuw besluit"},{"t":"Begrotingstekort","d":"dat de overheidsuitgaven groter zijn dan de inkomsten in een jaar"},{"t":"Staatsschuld","d":"de som van alle historische tekorten minus de overschotten"},{"t":"Sociale verzekering","d":"sociale zekerheid uit premies, met recht op uitkering bij werkloosheid of ziekte"}],"sam":"<div class=\"sam-intro\">De overheid heeft drie economische functies (<strong>allocatie</strong>, <strong>herverdeling</strong>, <strong>stabilisatie</strong>). Ze heft <strong>directe</strong> en <strong>indirecte</strong> belastingen, vaak <strong>progressief</strong>, en dempt de conjunctuur met <strong>automatische stabilisatoren</strong>. Uitgaven groter dan inkomsten geven een <strong>begrotingstekort</strong> en zo de <strong>staatsschuld</strong>.</div><div class=\"sam-head\">1. Functies en belastingen</div><p>De drie functies van Musgrave: <strong>allocatie</strong> (collectieve goederen leveren), <strong>herverdeling</strong> (ongelijkheid verkleinen) en <strong>stabilisatie</strong> (conjunctuur dempen). <strong>Directe belasting</strong> zit op inkomen of winst, <strong>indirecte belasting</strong> (btw, accijns) op bestedingen. Een <strong>progressief</strong> stelsel belast hogere inkomens met een hoger percentage; btw werkt juist <strong>regressief</strong>.</p><div class=\"sam-head\">2. Begroting en beleid</div><p><strong>Automatische stabilisatoren</strong> (zoals de WW) dempen de economie vanzelf. Bij een <strong>begrotingstekort</strong> geeft de overheid meer uit dan ze binnenkrijgt; de opgetelde tekorten vormen de <strong>staatsschuld</strong>. Bij <strong>keynesiaans</strong> beleid verlaagt de overheid in een recessie de belasting en geeft ze meer uit. De <strong>armoedeval</strong> maakt werken onaantrekkelijk als toeslagen wegvallen.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Allocatiefunctie</div><div class=\"sam-definitie-body\">de overheid levert collectieve goederen die de markt niet voortbrengt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Herverdelingsfunctie</div><div class=\"sam-definitie-body\">inkomensongelijkheid verkleinen via belasting en uitkeringen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stabilisatiefunctie</div><div class=\"sam-definitie-body\">conjunctuurschommelingen dempen door te stimuleren of af te remmen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Directe belasting</div><div class=\"sam-definitie-body\">belasting op inkomen of winst.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Indirecte belasting</div><div class=\"sam-definitie-body\">belasting op bestedingen, zoals btw en accijns.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Progressief belastingstelsel</div><div class=\"sam-definitie-body\">hoe hoger het inkomen, hoe hoger het belastingpercentage.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Automatische stabilisatoren</div><div class=\"sam-definitie-body\">mechanismen die de economie vanzelf dempen, zonder nieuw besluit.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Begrotingstekort</div><div class=\"sam-definitie-body\">dat de overheidsuitgaven groter zijn dan de inkomsten in een jaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Staatsschuld</div><div class=\"sam-definitie-body\">de som van alle historische tekorten minus de overschotten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sociale verzekering</div><div class=\"sam-definitie-body\">sociale zekerheid uit premies, met recht op uitkering bij werkloosheid of ziekte.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Allocatiefunctie»</b> is collectieve goederen leveren, terwijl <b>«Herverdelingsfunctie»</b> ongelijkheid verkleinen is. <b>«Herverdelingsfunctie»</b> is ongelijkheid verkleinen, terwijl <b>«Stabilisatiefunctie»</b> conjunctuur dempen is. <b>«Stabilisatiefunctie»</b> is conjunctuur dempen, terwijl <b>«Allocatiefunctie»</b> collectieve goederen leveren is. <b>«Directe belasting»</b> is op inkomen of winst, terwijl <b>«Indirecte belasting»</b> op bestedingen is.</div>"},"E":{"sv":[{"v":"Wat is het verschil tussen conjuncturele en structurele werkloosheid?","o":["conjunctureel is tijdelijk door lage vraag, structureel door een mismatch","ze zijn hetzelfde","conjunctureel is door een mismatch","structureel is tijdelijk"],"c":0,"d":3,"u":"Vraaggebrek tegenover mismatch.","uo":["Klopt: vraaggebrek tegenover mismatch.","Nee, ze verschillen.","Nee, dat is structureel.","Nee, structureel is juist langdurig."],"uh":"Conjunctureel: lage vraag; structureel: mismatch."},{"v":"Wat is inflatie?","o":["een prijsdaling","een prijsstijging waardoor de koopkracht daalt","een hogere rente","een tekort aan geld"],"c":1,"d":2,"u":"Inflatie is prijsstijging, minder koopkracht.","uo":["Nee, dat is deflatie.","Klopt: inflatie is prijsstijging, minder koopkracht.","Nee, rente is iets anders.","Nee, dat is geen inflatie."],"uh":"Inflatie: prijzen stijgen, koopkracht daalt."},{"v":"Hoe kan de ECB inflatie bestrijden?","o":["meer geld uitgeven","de rente verlagen","de rente verhogen zodat lenen duurder wordt en de vraag daalt","de belasting verlagen"],"c":2,"d":3,"u":"Een hogere rente remt de bestedingen.","uo":["Nee, dat is begrotingsbeleid.","Nee, dat wakkert inflatie juist aan.","Klopt: een hogere rente remt de bestedingen.","Nee, dat is begrotingsbeleid."],"uh":"Bij inflatie: hogere rente (ECB)."},{"v":"Hoe bereken je het BBP via de bestedingsmethode?","o":["BBP = belasting + premies","BBP = loon + winst","BBP = export − import","BBP = C + I + O + (E − M)"],"c":3,"d":3,"u":"Consumptie + investeringen + overheid + (export − import).","uo":["Nee, dat is de lastendruk.","Nee, dat is de inkomensmethode.","Nee, dat is maar één onderdeel.","Klopt: consumptie + investeringen + overheid + (export − import)."],"uh":"Bestedingsmethode: C + I + O + (E − M)."},{"v":"Wat kenmerkt een hoogconjunctuur?","o":["groei boven de trend, lage werkloosheid, oververhitting dreigt","krimp en hoge werkloosheid","een stabiele economie zonder groei","deflatie"],"c":0,"d":2,"u":"In de hausse groeit de economie hard.","uo":["Klopt: in de hausse groeit de economie hard.","Nee, dat is laagconjunctuur.","Nee, er is juist groei.","Nee, deflatie hoort bij krimp."],"uh":"Hoogconjunctuur: groei boven trend, lage werkloosheid."},{"v":"Wat is het verschil tussen reëel en nominaal BBP?","o":["ze zijn hetzelfde","nominaal is niet gecorrigeerd, reëel wel voor inflatie","nominaal is gecorrigeerd voor inflatie","reëel telt alleen export"],"c":1,"d":3,"u":"Reëel BBP haalt de inflatie eruit.","uo":["Nee, ze verschillen.","Klopt: reëel BBP haalt de inflatie eruit.","Nee, dat is precies omgedraaid.","Nee, dat klopt niet."],"uh":"Nominaal: niet gecorrigeerd; reëel: wel, voor inflatie."},{"v":"Wat is bestedingsinflatie?","o":["een prijsdaling","inflatie door hogere productiekosten","inflatie door te veel vraag: veel geld, weinig goederen","een hogere rente"],"c":2,"d":3,"u":"Te veel vraag jaagt de prijzen op.","uo":["Nee, dat is deflatie.","Nee, dat is kosteninflatie.","Klopt: te veel vraag jaagt de prijzen op.","Nee, dat is beleid."],"uh":"Bestedingsinflatie: te veel vraag."},{"v":"Wat is de inflatiedoelstelling van de ECB?","o":["de inflatie negatief maken","de inflatie op 0% houden","de inflatie zo hoog mogelijk maken","de inflatie op middellange termijn rond de 2% houden"],"c":3,"d":2,"u":"De ECB mikt op ongeveer 2%.","uo":["Nee, deflatie is gevaarlijk.","Nee, wat deflatiegevaar geeft.","Nee, dat is juist onwenselijk.","Klopt: de ECB mikt op ongeveer 2%."],"uh":"ECB-doel: inflatie rond 2%."},{"v":"Hoe beïnvloedt een lage rente de economie?","o":["lenen wordt goedkoper, consumptie en investeringen stijgen","lenen wordt duurder","de bestedingen dalen","er verandert niets"],"c":0,"d":2,"u":"Goedkoop geld jaagt bestedingen aan.","uo":["Klopt: goedkoop geld jaagt bestedingen aan.","Nee, dat is bij een hoge rente.","Nee, ze stijgen juist.","Nee, er is wel effect."],"uh":"Lage rente: goedkoper lenen, meer bestedingen."},{"v":"Wat is kosteninflatie?","o":["inflatie door te veel vraag","inflatie doordat hogere productiekosten worden doorberekend","een prijsdaling","een renteverhoging"],"c":1,"d":3,"u":"Duurdere grondstoffen of lonen verhogen de prijzen.","uo":["Nee, dat is bestedingsinflatie.","Klopt: duurdere grondstoffen of lonen verhogen de prijzen.","Nee, dat is deflatie.","Nee, dat is beleid."],"uh":"Kosteninflatie: hogere kosten doorberekend."},{"v":"Wat meet de CPI?","o":["de werkloosheid","de totale productie van een land","de prijsontwikkeling van een vast pakket van een huishouden","de staatsschuld"],"c":2,"d":3,"u":"De CPI volgt een vast boodschappenpakket.","uo":["Nee, dat is een arbeidsmarktcijfer.","Nee, dat is het BBP.","Klopt: de CPI volgt een vast boodschappenpakket.","Nee, dat is een schuld."],"uh":"CPI: prijzen van een vast pakket."},{"v":"Wat is frictiewerkloosheid?","o":["werkloosheid door seizoenen","werkloosheid door een blijvende mismatch","werkloosheid door lage vraag","tijdelijke werkloosheid van mensen tussen twee banen in"],"c":3,"d":3,"u":"Kort werkloos tijdens het wisselen van baan.","uo":["Nee, dat is seizoenswerkloosheid.","Nee, dat is structureel.","Nee, dat is conjunctureel.","Klopt: kort werkloos tijdens het wisselen van baan."],"uh":"Frictiewerkloosheid: kort, tussen twee banen."},{"v":"Waarom is deflatie gevaarlijk?","o":["mensen stellen aankopen uit, waardoor de economie krimpt","de prijzen stijgen te snel","de rente wordt te hoog","de export stijgt te hard"],"c":0,"d":3,"u":"Dalende prijzen ontmoedigen kopen nu.","uo":["Klopt: dalende prijzen ontmoedigen kopen nu.","Nee, dat is inflatie.","Nee, dat is niet de kern.","Nee, dat is geen deflatie-effect."],"uh":"Deflatie: aankopen uitgesteld, economie krimpt."},{"v":"Welke fase kenmerkt zich door twee kwartalen krimp achter elkaar?","o":["een hoogconjunctuur","een recessie","een boom","een herstel"],"c":1,"d":2,"u":"Twee kwartalen krimp is een recessie.","uo":["Nee, dat is juist groei.","Klopt: twee kwartalen krimp is een recessie.","Nee, dat is een piek.","Nee, dat is juist opgaand."],"uh":"Recessie: twee kwartalen krimp."},{"v":"Iemands vak verdwijnt en zijn vaardigheden passen niet meer. Welk begrip past hierbij?","o":["Kosteninflatie","Bestedingsinflatie","Structurele werkloosheid","Recessie"],"c":2,"d":1,"u":"Iemands vak verdwijnt en zijn vaardigheden passen niet meer. Dat past bij Structurele werkloosheid: mismatch.","uo":["Nee, dat hoort bij Kosteninflatie: hogere kosten doorberekend.","Nee, dat hoort bij Bestedingsinflatie: te veel vraag.","Klopt: mismatch.","Nee, dat hoort bij Recessie: twee kwartalen krimp."],"uh":"Structurele werkloosheid: mismatch."},{"v":"Het BBP nadat je de prijsstijging eruit hebt gehaald. Om welk begrip gaat het?","o":["Recessie","Inflatie","Conjuncturele werkloosheid","Reëel BBP"],"c":3,"d":1,"u":"Het BBP nadat je de prijsstijging eruit hebt gehaald. Dat past bij Reëel BBP: gecorrigeerd voor inflatie.","uo":["Nee, dat hoort bij Recessie: twee kwartalen krimp.","Nee, dat hoort bij Inflatie: prijzen stijgen, koopkracht daalt.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Klopt: gecorrigeerd voor inflatie."],"uh":"Reëel BBP: gecorrigeerd voor inflatie."},{"v":"Het BBP gecorrigeerd voor inflatie. Welk begrip herken je hier?","o":["Reëel BBP","Inflatie","Conjuncturele werkloosheid","Recessie"],"c":0,"d":1,"u":"Het BBP gecorrigeerd voor inflatie. Dat past bij Reëel BBP: gecorrigeerd voor inflatie.","uo":["Klopt: gecorrigeerd voor inflatie.","Nee, dat hoort bij Inflatie: prijzen stijgen, koopkracht daalt.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Nee, dat hoort bij Recessie: twee kwartalen krimp."],"uh":"Reëel BBP: gecorrigeerd voor inflatie."},{"v":"De prijsindex van een huishoudpakket. Wat is hier aan de hand?","o":["Kosteninflatie","CPI","Reëel BBP","Structurele werkloosheid"],"c":1,"d":1,"u":"De prijsindex van een huishoudpakket. Dat past bij CPI: prijzen vast pakket.","uo":["Nee, dat hoort bij Kosteninflatie: hogere kosten doorberekend.","Klopt: prijzen vast pakket.","Nee, dat hoort bij Reëel BBP: gecorrigeerd voor inflatie.","Nee, dat hoort bij Structurele werkloosheid: mismatch."],"uh":"CPI: prijzen vast pakket."},{"v":"De prijsindex van een vast boodschappenpakket. Welk begrip past hierbij?","o":["Reëel BBP","Kosteninflatie","CPI","Structurele werkloosheid"],"c":2,"d":1,"u":"De prijsindex van een vast boodschappenpakket. Dat past bij CPI: prijzen vast pakket.","uo":["Nee, dat hoort bij Reëel BBP: gecorrigeerd voor inflatie.","Nee, dat hoort bij Kosteninflatie: hogere kosten doorberekend.","Klopt: prijzen vast pakket.","Nee, dat hoort bij Structurele werkloosheid: mismatch."],"uh":"CPI: prijzen vast pakket."},{"v":"De op- en neergang van de economie. Om welk begrip gaat het?","o":["Bestedingsinflatie","Conjuncturele werkloosheid","CPI","Conjunctuur"],"c":3,"d":1,"u":"De op- en neergang van de economie. Dat past bij Conjunctuur: op- en neergang economie.","uo":["Nee, dat hoort bij Bestedingsinflatie: te veel vraag.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Nee, dat hoort bij CPI: prijzen vast pakket.","Klopt: op- en neergang economie."],"uh":"Conjunctuur: op- en neergang economie."},{"v":"Inflatie door hogere productiekosten. Welk begrip herken je hier?","o":["Kosteninflatie","Bestedingsinflatie","Recessie","Conjuncturele werkloosheid"],"c":0,"d":2,"u":"Inflatie door hogere productiekosten. Dat past bij Kosteninflatie: hogere kosten doorberekend.","uo":["Klopt: hogere kosten doorberekend.","Nee, dat hoort bij Bestedingsinflatie: te veel vraag.","Nee, dat hoort bij Recessie: twee kwartalen krimp.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag."],"uh":"Kosteninflatie: hogere kosten doorberekend."},{"v":"Duurdere grondstoffen worden in de prijzen doorberekend. Wat is hier aan de hand?","o":["Conjunctuur","Kosteninflatie","Frictiewerkloosheid","Recessie"],"c":1,"d":1,"u":"Duurdere grondstoffen worden in de prijzen doorberekend. Dat past bij Kosteninflatie: hogere kosten doorberekend.","uo":["Nee, dat hoort bij Conjunctuur: op- en neergang economie.","Klopt: hogere kosten doorberekend.","Nee, dat hoort bij Frictiewerkloosheid: tussen twee banen.","Nee, dat hoort bij Recessie: twee kwartalen krimp."],"uh":"Kosteninflatie: hogere kosten doorberekend."},{"v":"Een prijsstijging waardoor de koopkracht daalt. Welk begrip past hierbij?","o":["Recessie","Conjunctuur","Inflatie","CPI"],"c":2,"d":2,"u":"Een prijsstijging waardoor de koopkracht daalt. Dat past bij Inflatie: prijzen stijgen, koopkracht daalt.","uo":["Nee, dat hoort bij Recessie: twee kwartalen krimp.","Nee, dat hoort bij Conjunctuur: op- en neergang economie.","Klopt: prijzen stijgen, koopkracht daalt.","Nee, dat hoort bij CPI: prijzen vast pakket."],"uh":"Inflatie: prijzen stijgen, koopkracht daalt."},{"v":"De prijzen stijgen algemeen en je geld wordt minder waard. Om welk begrip gaat het?","o":["CPI","Conjuncturele werkloosheid","Kosteninflatie","Inflatie"],"c":3,"d":1,"u":"De prijzen stijgen algemeen en je geld wordt minder waard. Dat past bij Inflatie: prijzen stijgen, koopkracht daalt.","uo":["Nee, dat hoort bij CPI: prijzen vast pakket.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Nee, dat hoort bij Kosteninflatie: hogere kosten doorberekend.","Klopt: prijzen stijgen, koopkracht daalt."],"uh":"Inflatie: prijzen stijgen, koopkracht daalt."},{"v":"Tijdelijke werkloosheid tussen twee banen. Welk begrip herken je hier?","o":["Frictiewerkloosheid","Structurele werkloosheid","Conjuncturele werkloosheid","Conjunctuur"],"c":0,"d":2,"u":"Tijdelijke werkloosheid tussen twee banen. Dat past bij Frictiewerkloosheid: tussen twee banen.","uo":["Klopt: tussen twee banen.","Nee, dat hoort bij Structurele werkloosheid: mismatch.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Nee, dat hoort bij Conjunctuur: op- en neergang economie."],"uh":"Frictiewerkloosheid: tussen twee banen."},{"v":"Twee kwartalen economische krimp. Wat is hier aan de hand?","o":["Conjuncturele werkloosheid","Recessie","Inflatie","Reëel BBP"],"c":1,"d":1,"u":"Twee kwartalen economische krimp. Dat past bij Recessie: twee kwartalen krimp.","uo":["Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Klopt: twee kwartalen krimp.","Nee, dat hoort bij Inflatie: prijzen stijgen, koopkracht daalt.","Nee, dat hoort bij Reëel BBP: gecorrigeerd voor inflatie."],"uh":"Recessie: twee kwartalen krimp."},{"v":"Tijdelijke werkloosheid door lage vraag. Welk begrip past hierbij?","o":["Conjunctuur","Structurele werkloosheid","Conjuncturele werkloosheid","Inflatie"],"c":2,"d":2,"u":"Tijdelijke werkloosheid door lage vraag. Dat past bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","uo":["Nee, dat hoort bij Conjunctuur: op- en neergang economie.","Nee, dat hoort bij Structurele werkloosheid: mismatch.","Klopt: tijdelijk door lage vraag.","Nee, dat hoort bij Inflatie: prijzen stijgen, koopkracht daalt."],"uh":"Conjuncturele werkloosheid: tijdelijk door lage vraag."},{"v":"De economie beweegt op en neer rond de trend. Om welk begrip gaat het?","o":["Bestedingsinflatie","Conjuncturele werkloosheid","CPI","Conjunctuur"],"c":3,"d":1,"u":"De economie beweegt op en neer rond de trend. Dat past bij Conjunctuur: op- en neergang economie.","uo":["Nee, dat hoort bij Bestedingsinflatie: te veel vraag.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Nee, dat hoort bij CPI: prijzen vast pakket.","Klopt: op- en neergang economie."],"uh":"Conjunctuur: op- en neergang economie."},{"v":"Werkloosheid door een mismatch. Welk begrip herken je hier?","o":["Structurele werkloosheid","Conjuncturele werkloosheid","Conjunctuur","Frictiewerkloosheid"],"c":0,"d":2,"u":"Werkloosheid door een mismatch. Dat past bij Structurele werkloosheid: mismatch.","uo":["Klopt: mismatch.","Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Nee, dat hoort bij Conjunctuur: op- en neergang economie.","Nee, dat hoort bij Frictiewerkloosheid: tussen twee banen."],"uh":"Structurele werkloosheid: mismatch."},{"v":"Inflatie door te veel vraag. Wat is hier aan de hand?","o":["Kosteninflatie","Bestedingsinflatie","Recessie","Inflatie"],"c":1,"d":3,"u":"Inflatie door te veel vraag. Dat past bij Bestedingsinflatie: te veel vraag.","uo":["Nee, dat hoort bij Kosteninflatie: hogere kosten doorberekend.","Klopt: te veel vraag.","Nee, dat hoort bij Recessie: twee kwartalen krimp.","Nee, dat hoort bij Inflatie: prijzen stijgen, koopkracht daalt."],"uh":"Bestedingsinflatie: te veel vraag."},{"v":"In een recessie ontslaan bedrijven personeel door te lage vraag. Welk begrip past hierbij?","o":["Bestedingsinflatie","Inflatie","Conjuncturele werkloosheid","Conjunctuur"],"c":2,"d":1,"u":"In een recessie ontslaan bedrijven personeel door te lage vraag. Dat past bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","uo":["Nee, dat hoort bij Bestedingsinflatie: te veel vraag.","Nee, dat hoort bij Inflatie: prijzen stijgen, koopkracht daalt.","Klopt: tijdelijk door lage vraag.","Nee, dat hoort bij Conjunctuur: op- en neergang economie."],"uh":"Conjuncturele werkloosheid: tijdelijk door lage vraag."},{"v":"Er is te veel vraag: veel geld jaagt op weinig goederen. Om welk begrip gaat het?","o":["Conjuncturele werkloosheid","Kosteninflatie","Frictiewerkloosheid","Bestedingsinflatie"],"c":3,"d":2,"u":"Er is te veel vraag: veel geld jaagt op weinig goederen. Dat past bij Bestedingsinflatie: te veel vraag.","uo":["Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Nee, dat hoort bij Kosteninflatie: hogere kosten doorberekend.","Nee, dat hoort bij Frictiewerkloosheid: tussen twee banen.","Klopt: te veel vraag."],"uh":"Bestedingsinflatie: te veel vraag."},{"v":"Iemand is kort werkloos tussen twee banen in. Welk begrip herken je hier?","o":["Frictiewerkloosheid","Structurele werkloosheid","Kosteninflatie","Recessie"],"c":0,"d":3,"u":"Iemand is kort werkloos tussen twee banen in. Dat past bij Frictiewerkloosheid: tussen twee banen.","uo":["Klopt: tussen twee banen.","Nee, dat hoort bij Structurele werkloosheid: mismatch.","Nee, dat hoort bij Kosteninflatie: hogere kosten doorberekend.","Nee, dat hoort bij Recessie: twee kwartalen krimp."],"uh":"Frictiewerkloosheid: tussen twee banen."},{"v":"De economie krimpt twee kwartalen achter elkaar. Wat is hier aan de hand?","o":["Conjuncturele werkloosheid","Recessie","Inflatie","Reëel BBP"],"c":1,"d":1,"u":"De economie krimpt twee kwartalen achter elkaar. Dat past bij Recessie: twee kwartalen krimp.","uo":["Nee, dat hoort bij Conjuncturele werkloosheid: tijdelijk door lage vraag.","Klopt: twee kwartalen krimp.","Nee, dat hoort bij Inflatie: prijzen stijgen, koopkracht daalt.","Nee, dat hoort bij Reëel BBP: gecorrigeerd voor inflatie."],"uh":"Recessie: twee kwartalen krimp."}],"oe":[{"bron":"Artikel","ctx":"De wereldeconomie is sterk met elkaar verbonden door handel, investeringen en internationale productieketens. Veel producten worden in verschillende landen gemaakt: grondstoffen uit Afrika, onderdelen uit Azië en assemblage in Europa. Deze globalisering biedt kansen voor economische groei, maar maakt landen ook afhankelijk van elkaar. Wanneer één schakel in de keten uitvalt, bijvoorbeeld door een pandemie of geopolitieke spanningen, kunnen productieprocessen wereldwijd stilvallen. Tegelijkertijd profiteren landen van specialisatie: ieder land produceert waar het relatief goed in is. Hierdoor stijgt de totale welvaart. De uitdaging is om de voordelen van globalisering te benutten zonder te kwetsbaar te worden.","v":"Leg uit hoe specialisatie bijdraagt aan internationale handel.","o":[""],"c":0,"u":"Specialisatie betekent dat landen produceren waar ze relatief goed in zijn. Hierdoor kunnen ze efficiënter produceren. Landen ruilen deze producten met elkaar. Dit verhoogt de totale welvaart. Specialisatie vormt dus de basis van internationale handel."},{"bron":"Grafiek","ctx":"Grafiek-beschrijving: 'Lijngrafiek met wisselkoers euro-dollar tussen 2010 en 2025. De koers schommelt tussen 1,05 en 1,35.'","v":"Leg uit hoe een dalende euro invloed heeft op de export van Nederland.","o":[""],"c":0,"u":"Een dalende euro maakt Nederlandse producten goedkoper voor het buitenland. Hierdoor stijgt de export. Buitenlandse kopers kunnen meer kopen voor dezelfde hoeveelheid dollars. Een zwakkere euro versterkt dus de concurrentiepositie van exportbedrijven."},{"bron":"Artikel","ctx":"Ontwikkelingslanden proberen hun economie te versterken door te investeren in onderwijs, infrastructuur en industrie. Internationale organisaties zoals de Wereldbank en het IMF bieden leningen en advies om deze ontwikkeling te ondersteunen. Tegelijkertijd zijn veel landen afhankelijk van de export van grondstoffen, waardoor hun economie kwetsbaar is voor prijsschommelingen. Diversificatie is daarom belangrijk: door meer sectoren te ontwikkelen wordt de economie stabieler. Handelsovereenkomsten kunnen helpen om toegang te krijgen tot internationale markten, maar brengen ook verplichtingen met zich mee.","v":"Leg uit waarom afhankelijkheid van grondstoffen een risico vormt voor ontwikkelingslanden.","o":[""],"c":0,"u":"Grondstofprijzen schommelen sterk. Wanneer prijzen dalen, dalen de inkomsten van het land. Hierdoor ontstaat economische instabiliteit. Landen die weinig andere sectoren hebben, zijn extra kwetsbaar. Diversificatie maakt de economie stabieler."},{"bron":"Foto","ctx":"Foto-beschrijving: 'Containerschepen in de haven van Rotterdam met stapels containers uit verschillende landen.'","v":"Leg uit waarom havens zoals Rotterdam belangrijk zijn voor de Nederlandse economie.","o":[""],"c":0,"u":"Rotterdam is een toegangspoort tot Europa. Goederen worden snel doorgevoerd naar het achterland. Dit levert veel werkgelegenheid op. Ook versterkt het de positie van Nederland in internationale handel. Havens zijn dus cruciaal voor de economie."},{"bron":"Artikel","ctx":"De Europese Unie speelt een belangrijke rol in de economie van Nederland. Door de interne markt kunnen goederen, diensten, kapitaal en personen vrij bewegen. Dit vergroot de handel tussen lidstaten en maakt productie efficiënter. Bedrijven profiteren van een grotere afzetmarkt en minder handelsbarrières. Tegelijkertijd brengt EU-lidmaatschap verplichtingen met zich mee, zoals bijdragen aan de begroting en naleving van regels. De voordelen van samenwerking wegen voor Nederland zwaar, omdat de economie sterk afhankelijk is van internationale handel.","v":"Leg uit waarom Nederland veel voordeel heeft van de interne markt van de EU.","o":[""],"c":0,"u":"De interne markt maakt handel eenvoudiger en goedkoper. Bedrijven hebben toegang tot een grote afzetmarkt. Er zijn minder handelsbarrières en regels zijn gelijk. Hierdoor kan Nederland efficiënter produceren en meer exporteren. De economie profiteert sterk van EU-samenwerking."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 6)","ctx":"De economie bevindt zich in een laagconjunctuur. De overheid kan anticyclisch begrotingsbeleid voeren.","v":"Noem twee voorbeelden van anticyclisch begrotingsbeleid van de overheid in een laagconjunctuur.","o":[""],"c":0,"u":"Bijvoorbeeld: belastingen verlagen (zoals loon- of btw-belasting) en overheidsuitgaven of uitkeringen verhogen. Beide stimuleren de bestedingen. Let op: monetair beleid (rente) hoort hier niet bij - dat is van de centrale bank."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 7)","ctx":"In een laagconjunctuur is de inflatie lager dan de doelstelling van de centrale bank. De bank zet het rente-instrument in.","v":"Verhoogt of verlaagt de centrale bank de rente om de inflatie te laten stijgen? Leg uit.","o":[""],"c":0,"u":"Verlagen: een lagere rente maakt lenen aantrekkelijker en sparen minder aantrekkelijk, waardoor consumptie en investeringen (de bestedingen) stijgen. Daardoor neemt de (bestedings)inflatie toe."},{"bron":"HAVO Economie CE 2025 Tijdvak 1 (vraag 18)","ctx":"De Nederlandse overheid wijst een groot deel van de CO2-emissierechten gratis toe aan bedrijven die vooral voor de export produceren.","v":"Leg uit dat het grotendeels toewijzen van emissierechten aan internationaal opererende bedrijven een vorm van protectie is.","o":[""],"c":0,"u":"Door de gratis rechten stijgen de kosten van deze exporteurs minder dan die van hun buitenlandse concurrenten, en blijft de productie in eigen land. Zo beschermt de overheid de eigen productie en werkgelegenheid - dat is protectie."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 7 (HA-1210-a-25-1-o)","ctx":"Het BBP van Nederland groeide in 2024 met 2,1%. De inflatie was 3,2%.","v":"Bereken het reele BBP-groeicijfer en geef aan wat dit betekent voor de koopkracht.","o":[""],"c":0,"u":"Reeel BBP-groei = 2,1% - 3,2% = -1,1%.\nDe reele koopkracht daalt: de economie produceert minder in reele termen ondanks nominale groei."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 8 (HA-1210-a-25-1-o)","ctx":"Nederland exporteert voor EUR 800 miljard en importeert voor EUR 750 miljard.","v":"(a) Bereken het handelssaldo.\n(b) Hoe heet dit saldo en is het positief of negatief?","o":[""],"c":0,"u":"(a) 800 - 750 = EUR 50 miljard.\n(b) Handelsoverschot / positief saldo op de lopende rekening."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 9 (HA-1210-a-25-1-o)","ctx":"De ECB verhoogt de beleidsrente van 3,5% naar 4,5%.","v":"Leg uit welk effect dit heeft op inflatie en op economische groei.","o":[""],"c":0,"u":"Hogere rente maakt lenen duurder: minder consumptie en investeringen. Vraag daalt, waardoor inflatie afneemt. Maar ook economische groei vertraagt (minder bestedingen)."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 10 (HA-1210-a-25-1-o)","ctx":"Nederland en Belgie produceren software en bloemen. Nederland: software 4u, bloemen 2u. Belgie: software 6u, bloemen 3u.","v":"Heeft een van beide landen een comparatief voordeel in software? Motiveer.","o":[""],"c":0,"u":"Opportuniteitskosten software:\nNederland: 4u/2u = 2 bloemen per software\nBelgie: 6u/3u = 2 bloemen per software\nGeen comparatief voordeel: opportuniteitskosten zijn gelijk, dus geen basis voor specialisatie op basis van comparatief voordeel."},{"bron":"HAVO Economie CE 2025 Tijdvak 1, vraag 11 (HA-1210-a-25-1-o)","ctx":"De werkloosheid in Nederland bedraagt 4,2%. Het CBS telt iemand als werkloos als hij actief zoekt naar werk.","v":"Noem twee typen werkloosheid en beschrijf elk kort.","o":[""],"c":0,"u":"(1) Frictiewerkloosheid: tijdelijk werkloos bij baanwisseling. (2) Structurele werkloosheid: langdurig werkloos door mismatch vaardigheden/vraag of technologische veranderingen."}],"begrippen":[{"t":"Conjuncturele werkloosheid","d":"tijdelijke werkloosheid door een te lage vraag"},{"t":"Structurele werkloosheid","d":"werkloosheid door een mismatch tussen vaardigheden en banen"},{"t":"Frictiewerkloosheid","d":"tijdelijke werkloosheid van mensen tussen twee banen in"},{"t":"Inflatie","d":"een algemene prijsstijging waardoor de koopkracht daalt"},{"t":"Bestedingsinflatie","d":"inflatie door te veel vraag: veel geld, weinig goederen"},{"t":"Kosteninflatie","d":"inflatie doordat hogere productiekosten worden doorberekend"},{"t":"Conjunctuur","d":"de op- en neergang van de economie rond de trend"},{"t":"Reëel BBP","d":"het BBP gecorrigeerd voor inflatie"},{"t":"CPI","d":"de prijsindex van een vast pakket van een huishouden"},{"t":"Recessie","d":"twee kwartalen economische krimp achter elkaar"}],"sam":"<div class=\"sam-intro\">De economie beweegt in een <strong>conjunctuur</strong> van hoog- en laagconjunctuur. Er zijn meerdere soorten <strong>werkloosheid</strong> (conjunctureel, structureel, frictie). <strong>Inflatie</strong> holt de koopkracht uit; de <strong>ECB</strong> mikt op ongeveer 2% en stuurt met de <strong>rente</strong>. Het <strong>BBP</strong> bereken je met de bestedingsmethode C + I + O + (E − M).</div><div class=\"sam-head\">1. Conjunctuur en werkloosheid</div><p>In een <strong>hoogconjunctuur</strong> groeit de economie boven de trend met lage werkloosheid; in een <strong>laagconjunctuur</strong> onder de trend met stijgende werkloosheid. Een <strong>recessie</strong> is twee kwartalen krimp achter elkaar. <strong>Conjuncturele</strong> werkloosheid is tijdelijk door lage vraag, <strong>structurele</strong> door een mismatch, <strong>frictiewerkloosheid</strong> zit tussen twee banen in.</p><div class=\"sam-head\">2. Inflatie en beleid</div><p><strong>Inflatie</strong> is een prijsstijging die de koopkracht verlaagt; <strong>bestedingsinflatie</strong> ontstaat door te veel vraag, <strong>kosteninflatie</strong> door hogere productiekosten. De <strong>CPI</strong> meet de prijzen van een vast pakket. De <strong>ECB</strong> mikt op ongeveer 2% en verhoogt de rente om inflatie te remmen. <strong>Deflatie</strong> is gevaarlijk omdat mensen aankopen uitstellen.</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">BBP (bestedingsmethode)</div><div class=\"sam-formula-eq\">BBP = C + I + O + (E − M)</div><div class=\"sam-formula-note\">Consumptie + investeringen + overheid + (export − import).</div></div><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Conjuncturele werkloosheid</div><div class=\"sam-definitie-body\">tijdelijke werkloosheid door een te lage vraag.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Structurele werkloosheid</div><div class=\"sam-definitie-body\">werkloosheid door een mismatch tussen vaardigheden en banen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Frictiewerkloosheid</div><div class=\"sam-definitie-body\">tijdelijke werkloosheid van mensen tussen twee banen in.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inflatie</div><div class=\"sam-definitie-body\">een algemene prijsstijging waardoor de koopkracht daalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bestedingsinflatie</div><div class=\"sam-definitie-body\">inflatie door te veel vraag: veel geld, weinig goederen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kosteninflatie</div><div class=\"sam-definitie-body\">inflatie doordat hogere productiekosten worden doorberekend.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Conjunctuur</div><div class=\"sam-definitie-body\">de op- en neergang van de economie rond de trend.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Reëel BBP</div><div class=\"sam-definitie-body\">het BBP gecorrigeerd voor inflatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">CPI</div><div class=\"sam-definitie-body\">de prijsindex van een vast pakket van een huishouden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Recessie</div><div class=\"sam-definitie-body\">twee kwartalen economische krimp achter elkaar.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Conjuncturele werkloosheid»</b> is tijdelijk door lage vraag, terwijl <b>«Structurele werkloosheid»</b> mismatch is. <b>«Frictiewerkloosheid»</b> is tussen twee banen, terwijl <b>«Structurele werkloosheid»</b> mismatch is. <b>«Bestedingsinflatie»</b> is te veel vraag, terwijl <b>«Kosteninflatie»</b> hogere kosten doorberekend is. <b>«Conjunctuur»</b> is op- en neergang economie, terwijl <b>«Recessie»</b> twee kwartalen krimp is.</div>"}});